class AlexLmpApp extends StatelessWidget {
  const AlexLmpApp({super.key});

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: appState,
      builder: (context, _) {
        final pal = appState.palette;
        final community = appState.community;
        final cs = appState.m3Colors
            ? appState.scheme.copyWith(
                surface: pal.bg,
                surfaceContainerLow: appState.b('pure_black') ? Colors.black : null,
              )
            : ColorScheme.dark(
                primary: pal.accent,
                onPrimary: pal.onAccent,
                secondary: pal.accent,
                surface: pal.bg,
                surfaceContainer: pal.surface,
              );
        final textScale = appState.d('text_scale', 1.0);
        return MaterialApp(
          title: 'AlexLMP',
          debugShowCheckedModeBanner: false,
          themeMode: ThemeMode.dark,
          darkTheme: ThemeData(
            useMaterial3: true,
            brightness: Brightness.dark,
            scaffoldBackgroundColor: pal.bg,
            colorScheme: cs,
            splashFactory: InkSparkle.splashFactory,
            fontFamily: 'Roboto',
            // Android's predictive back: swipe back to peek at the screen behind.
            pageTransitionsTheme: const PageTransitionsTheme(builders: {
              TargetPlatform.android: PredictiveBackPageTransitionsBuilder(),
            }),
            bottomSheetTheme: BottomSheetThemeData(
              backgroundColor: community ? cs.surfaceContainerLow : null,
            ),
            popupMenuTheme: PopupMenuThemeData(
              color: cs.surfaceContainerHigh,
              elevation: 6,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(20)),
            ),
            dialogTheme: DialogTheme(
              backgroundColor: cs.surfaceContainerHigh,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(28)),
            ),
            snackBarTheme: SnackBarThemeData(
              behavior: SnackBarBehavior.floating,
              backgroundColor: cs.inverseSurface,
              contentTextStyle: TextStyle(
                color: cs.onInverseSurface,
                fontWeight: FontWeight.w500,
                fontSize: 14.5,
              ),
              actionTextColor: cs.inversePrimary,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16)),
            ),
            tooltipTheme: TooltipThemeData(
              decoration: BoxDecoration(
                color: cs.inverseSurface,
                borderRadius: BorderRadius.circular(10),
              ),
              textStyle: TextStyle(color: cs.onInverseSurface),
            ),
            progressIndicatorTheme: ProgressIndicatorThemeData(
              color: cs.primary,
              linearTrackColor: cs.primary.withOpacity(0.18),
              circularTrackColor: Colors.transparent,
            ),
          ),
          builder: (context, child) {
            final mq = MediaQuery.of(context);
            return MediaQuery(
              data: mq.copyWith(textScaler: TextScaler.linear(textScale)),
              child: LaunchSplash(child: child ?? const SizedBox.shrink()),
            );
          },
          home: appState.b('setup_done')
              ? const AlexLmpRoot()
              : const SetupScreen(),
        );
      },
    );
  }
}

void openPlayer(BuildContext context) {
  if (audioHandler.tracks.isEmpty) {
    showAddMusicSheet(context);
    return;
  }
  if (glassPaused.value) return; // already open
  glassPaused.value = true;
  Navigator.of(context)
      .push(
    PageRouteBuilder(
      opaque: false,
      transitionDuration: const Duration(milliseconds: 520),
      reverseTransitionDuration: const Duration(milliseconds: 360),
      pageBuilder: (_, __, ___) => const NowPlayingScreen(),
      transitionsBuilder: (_, anim, __, child) {
        final curved = CurvedAnimation(
          parent: anim,
          curve: kEmphasizedDecel,
          reverseCurve: kEmphasizedAccel,
        );
        return SlideTransition(
          position: Tween<Offset>(
            begin: const Offset(0, 0.08),
            end: Offset.zero,
          ).animate(curved),
          child: FadeTransition(opacity: curved, child: child),
        );
      },
    ),
  ).whenComplete(() => glassPaused.value = false);
}

void playAndOpen(BuildContext context, int index) {
  audioHandler.playIndex(index);
  openPlayer(context);
}

class AlexLmpRoot extends StatefulWidget {
  const AlexLmpRoot({super.key});

  @override
  State<AlexLmpRoot> createState() => _AlexLmpRootState();
}

class _AlexLmpRootState extends State<AlexLmpRoot> {
  int _tab = 0;
  int _dir = 1;
  int _libraryFilter = 0;

  AppLifecycleListener? _life;

  void _trackRecent() {
    final t = audioHandler.currentTrack;
    if (t != null) appState.addRecent(t.id);
  }

  @override
  void initState() {
    super.initState();
    appNotice.addListener(_onNotice);
    audioHandler.currentIndex.addListener(_trackRecent);
    startWidgetSync();
    // Pick up a new wallpaper colour when you come back to the app.
    _life = AppLifecycleListener(onResume: () {
      applyNativeSettings();
    });
    _askPermissionsThenScan();
    WidgetsBinding.instance.addPostFrameCallback((_) => _onNotice());
  }

  /// Asks for everything the app needs right at launch (music access,
  /// notifications, and — once — background/battery permission), then scans.
  Future<void> _askPermissionsThenScan() async {
    if (Platform.isAndroid) {
      try {
        await ensureMediaPermissions(); // music files + notifications
        final prefs = await SharedPreferences.getInstance();
        final battery = await Permission.ignoreBatteryOptimizations.isGranted;
        if (!battery && !(prefs.getBool('asked_battery_opt') ?? false)) {
          await prefs.setBool('asked_battery_opt', true);
          await Permission.ignoreBatteryOptimizations.request();
        }
      } catch (_) {}
    }
    if (appState.b('auto_scan', true)) await scanDeviceAudio();
    await audioHandler.restoreLastSession();
    applyNativeSettings();
    if (mounted) checkForUpdates(context);
  }

  @override
  void dispose() {
    appNotice.removeListener(_onNotice);
    audioHandler.currentIndex.removeListener(_trackRecent);
    _life?.dispose();
    super.dispose();
  }

  /// Only real problems get a pop-up (with their raw error). Confirmations
  /// and progress messages ("Finding artist…", "Added to likes",
  /// "Playing next", "Saving…") are skipped.
  static bool _worthShowing(String m) {
    final s = m.toLowerCase();
    return s.contains('couldn\'t') ||
        s.contains('failed') ||
        s.contains('interrupted') ||
        s.contains('isn\'t') ||
        s.contains('up to date');
  }

  void _onNotice() {
    final msg = appNotice.value;
    if (msg == null || !mounted) return;
    appNotice.value = null;
    if (!_worthShowing(msg)) return;
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          content: Text(msg),
          behavior: SnackBarBehavior.floating,
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 190),
        ),
      );
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge([
        appState,
        audioHandler.libraryRevision,
        audioHandler.currentIndex,
        scanning,
        glassPaused,
      ]),
      builder: (context, _) {
        // While the player is open this screen is hidden underneath it:
        // freeze it (no rebuilds when songs change, no animations ticking)
        // so all the phone's power goes to the player.
        final paused = glassPaused.value;
        if (paused && _frozen != null) return _frozen!;
        final screen = TickerMode(enabled: !paused, child: _screen(context));
        _frozen = paused ? screen : null;
        return screen;
      },
    );
  }

  Widget? _frozen;

  Widget _screen(BuildContext context) {
    {
      {
        final pal = appState.palette;
        final tracks = audioHandler.tracks;
        final bottomInset = MediaQuery.of(context).padding.bottom;

        if (appState.appStyle == 'apple') {
          return _amScaffold(context, pal, tracks);
        }
        if (appState.appStyle == 'prestige') {
          return _prestigeScaffold(context, pal, tracks);
        }
        if (appState.appStyle == 'plus') {
          return _plusScaffold(context, pal, tracks);
        }
        if (appState.appStyle == 'pocket') {
          return _pocketScaffold(context, pal, tracks);
        }

        return Scaffold(
          backgroundColor: pal.bg,
          body: Stack(
            children: [
              AuroraPlasmaBackground(
                accent: pal.accent,
                secondary: const Color(0xFFF09CE2),
              ),
              SafeArea(
                bottom: false,
                child: AnimatedSwitcher(
                  duration: const Duration(milliseconds: 380),
                  switchInCurve: kEmphasizedDecel,
                  switchOutCurve: kEmphasizedAccel,
                  transitionBuilder: (child, anim) {
                    final incoming = child.key == ValueKey(_tab);
                    final begin = Offset(0.08 * (incoming ? _dir : -_dir), 0);
                    return FadeTransition(
                      opacity: anim,
                      child: SlideTransition(
                        position: Tween<Offset>(begin: begin, end: Offset.zero)
                            .animate(anim),
                        child: child,
                      ),
                    );
                  },
                  child: KeyedSubtree(
                    key: ValueKey(_tab),
                    child: _tabBody(context, pal, tracks),
                  ),
                ),
              ),
              if (appState.community && !appState.liquidGlass)
                _m3Bottom(context, pal)
              else
              Positioned(
                left: 12,
                right: 12,
                bottom: bottomInset + 8,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (audioHandler.currentTrack != null)
                      Reveal(
                        dy: 40,
                        child: MiniPlayer(
                          track: audioHandler.currentTrack!,
                          palette: pal,
                        ),
                      ),
                    const SizedBox(height: 8),
                    Row(
                      children: [
                        Expanded(
                          child: appState.liquidGlass
                              ? LiquidGlassNavBar(
                                  selected: _tab,
                                  palette: pal,
                                  items: const [
                                    (Icons.home_rounded, 'Home'),
                                    (Icons.sensors_rounded, 'Mix'),
                                    (Icons.library_music_rounded, 'Library'),
                                  ],
                                  onSelect: (i) => setState(() {
                                    _dir = i >= _tab ? 1 : -1;
                                    _tab = i;
                                  }),
                                )
                              : _navBar(pal),
                        ),
                        const SizedBox(width: 10),
                        SquishyGesture(
                          onTap: () => showSearchSheet(context),
                          child: LiquidGlassBox(
                            realBlur: true,
                            borderRadius: BorderRadius.circular(32),
                            fallbackColor: pal.surface,
                            boxShadow: _shadow,
                            child: const SizedBox(
                              width: 64,
                              height: 64,
                              child: Icon(
                                Icons.search_rounded,
                                color: Color(0xFFD5DCE0),
                                size: 26,
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        );
      }
    }
  }

