  List<AmItem> _amTopArtistsAll(List<TrackItem> tracks) {
    final by = <String, List<TrackItem>>{};
    for (final t in tracks) {
      by.putIfAbsent(t.artist, () => []).add(t);
    }
    final keys = by.keys.toList()
      ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    return [
      for (final k in keys)
        AmItem(k, '', (s) => CustomAlbumArtwork(track: by[k]!.first),
            () => showArtistTracksSheet(context, k, by[k]!),
            circle: true),
    ];
  }

  List<AmItem> _amAlbums(List<TrackItem> tracks) {
    final by = <String, List<TrackItem>>{};
    for (final t in tracks) {
      by.putIfAbsent(t.album, () => []).add(t);
    }
    final keys = by.keys.toList()
      ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    return [
      for (final k in keys)
        AmItem(k, by[k]!.first.artist,
            (s) => CustomAlbumArtwork(track: by[k]!.first),
            () => showArtistTracksSheet(context, k, by[k]!)),
    ];
  }

  // ── Search ───────────────────────────────────────────────────────────

  Widget _amSearch(BuildContext context, AppPalette pal, AmData d) {
    final w = MediaQuery.of(context).size.width;
    final cell = (w - 44 - 16) / 2;
    final art = [...d.songs, ...d.recent];
    TrackItem? artFor(int i) => art.isEmpty ? null : art[(i * 7 + 3) % art.length];
    return ListView(
      padding: const EdgeInsets.only(bottom: 220),
      children: [
        amTitle('Search', actions: [_amMenu(context, pal)]),
        Padding(
          padding: const EdgeInsets.fromLTRB(22, 10, 22, 16),
          child: GestureDetector(
            onTap: () => showSearchSheet(context),
            child: Container(
              height: 58,
              padding: const EdgeInsets.symmetric(horizontal: 20),
              alignment: Alignment.centerLeft,
              decoration: BoxDecoration(
                color: const Color(0xFF1C1C1E),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: Colors.white10),
              ),
              child: const Text(
                'Artists, Songs, Albums and more',
                style: TextStyle(color: Colors.white54, fontSize: 18.5),
              ),
            ),
          ),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 22),
          child: Wrap(
            spacing: 16,
            runSpacing: 16,
            children: [
              for (var i = 0; i < kAmGenres.length; i++)
                AmGenreTile(
                  name: kAmGenres[i].$1,
                  color: kAmGenres[i].$2,
                  art: artFor(i),
                  width: cell,
                  onTap: () => showSearchSheet(context, query: kAmGenres[i].$3),
                ),
            ],
          ),
        ),
      ],
    );
  }

  /// Community style: standard Material 3 navigation bar (full width) with
  /// the mini player floating above it.
  Widget _m3Bottom(BuildContext context, AppPalette pal) {
    final cs = appState.scheme;
    return Positioned(
      left: 0,
      right: 0,
      bottom: 0,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (audioHandler.currentTrack != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 0, 12, 4),
              child: Reveal(
                dy: 40,
                child: MiniPlayer(
                  track: audioHandler.currentTrack!,
                  palette: pal,
                ),
              ),
            ),
          // The bar isn't at the top of the screen, so drop the status-bar
          // padding it would otherwise add above itself.
          MediaQuery.removePadding(
            context: context,
            removeTop: true,
            child: NavigationBarTheme(
            data: NavigationBarThemeData(
              backgroundColor: appState.b('pure_black')
                  ? const Color(0xFF0B0B0D)
                  : cs.surfaceContainer,
              indicatorColor: cs.secondaryContainer,
              iconTheme: WidgetStateProperty.resolveWith((st) => IconThemeData(
                    color: st.contains(WidgetState.selected)
                        ? cs.onSecondaryContainer
                        : cs.onSurfaceVariant,
                  )),
              labelTextStyle: WidgetStateProperty.resolveWith((st) => TextStyle(
                    fontSize: 12,
                    fontWeight: st.contains(WidgetState.selected)
                        ? FontWeight.w700
                        : FontWeight.w500,
                    color: st.contains(WidgetState.selected)
                        ? cs.onSurface
                        : cs.onSurfaceVariant,
                  )),
            ),
            child: NavigationBar(
              // Compact Material 3 height so the mini player sits low, like
              // the regular style.
              height: 62,
              labelBehavior: NavigationDestinationLabelBehavior.onlyShowSelected,
              selectedIndex: _tab,
              onDestinationSelected: (i) {
                if (i == 3) {
                  showSearchSheet(context);
                  return;
                }
                if (i != _tab) HapticFeedback.selectionClick();
                setState(() {
                  _dir = i >= _tab ? 1 : -1;
                  _tab = i;
                });
              },
              destinations: const [
                NavigationDestination(
                  icon: Icon(Icons.home_outlined),
                  selectedIcon: Icon(Icons.home_rounded),
                  label: 'Home',
                ),
                NavigationDestination(
                  icon: Icon(Icons.sensors_outlined),
                  selectedIcon: Icon(Icons.sensors_rounded),
                  label: 'Mix',
                ),
                NavigationDestination(
                  icon: Icon(Icons.library_music_outlined),
                  selectedIcon: Icon(Icons.library_music_rounded),
                  label: 'Library',
                ),
                NavigationDestination(
                  icon: Icon(Icons.search_rounded),
                  label: 'Search',
                ),
              ],
            ),
          ),
          ),
        ],
      ),
    );
  }

  Widget _tabBody(BuildContext context, AppPalette pal, List<TrackItem> allTracks,
      {int? tab}) {
    final tabNow = tab ?? _tab;
    final m3 = appState.community;
    final yt = appState.homeMode == 'youtube';
    // Local mode shows only files on your phone; YouTube mode shows your
    // YouTube Music home and library.
    final tracks = allTracks.where((t) => yt ? t.isYouTube : !t.isYouTube).toList();
    if (yt) {
      // Same layouts as Local mode, filled with YouTube Music.
      switch (tabNow) {
        case 1:
          return _ytMixTab(context, pal);
        case 2:
          return m3
              ? _libraryTabM3(context, pal, tracks)
              : _libraryTab(context, pal, tracks);
        default:
          return _ytHomeTab(context, pal);
      }
    }
    switch (tabNow) {
      case 1:
        return _mixTab(context, pal, tracks);
      case 2:
        return m3
            ? _libraryTabM3(context, pal, tracks)
            : _libraryTab(context, pal, tracks);
      default:
        return m3
            ? _homeTabM3(context, pal, tracks)
            : _homeTab(context, pal, tracks);
    }
  }

  // ═══════════════════ Local music / YouTube Music mode ═══════════════════

  Future<void> _setMode(String mode) async {
    if (mode == appState.homeMode) return;
    if (mode == 'youtube' && !ytAccount.value.signedIn) {
      await ytSignInFlow(context);
      if (!ytAccount.value.signedIn) return; // cancelled: stay on local
    }
    HapticFeedback.selectionClick();
    setState(() => _dir = mode == 'youtube' ? 1 : -1);
    appState.setStr('home_mode', mode);
  }

