        ],
        if (d.liked.isNotEmpty) ...[
          const SizedBox(height: 22),
          _sectionHeader('YOUR FAVORITES', 'Liked songs',
              trailing: _pillButton(pal, 'Open', () => openYtLikedMusic(context))),
          const SizedBox(height: 8),
