  /// Greeting that always stays on one line (shrinks if it has to).
  Widget _greetingText({required TextStyle style}) {
    return ValueListenableBuilder<YtAccount>(
      valueListenable: ytAccount,
      builder: (context, _, __) => FittedBox(
        fit: BoxFit.scaleDown,
        alignment: Alignment.centerLeft,
        child: Text(_greeting(), maxLines: 1, style: style),
      ),
    );
  }

  String _greeting() {
    final g = _greetingBase();
    final acc = ytAccount.value;
    final first = (acc.name ?? '').trim().split(RegExp(r'\s+')).first;
    if (!acc.signedIn || first.isEmpty || !appState.b('greet_name')) {
      return g;
    }
    return '$g, $first';
  }

  String _greetingBase() {
    final h = DateTime.now().hour;
    if (h < 5) return 'Good night';
    if (h < 12) return 'Good morning';
    if (h < 17) return 'Good afternoon';
    return 'Good evening';
  }

  Widget _roundIcon(AppPalette pal, IconData icon, VoidCallback onTap) {
    return SquishyGesture(
      onTap: onTap,
      child: Container(
        width: 42,
        height: 42,
        decoration: BoxDecoration(
          color: pal.surface,
          shape: BoxShape.circle,
          border: Border.all(color: Colors.white10),
        ),
        child: Icon(icon, color: const Color(0xFFD5DCE0), size: 22),
      ),
    );
  }

  Widget _accountButton(BuildContext context, AppPalette pal) {
    return ValueListenableBuilder<YtAccount>(
      valueListenable: ytAccount,
      builder: (context, acc, _) => SquishyGesture(
        onTap: () => showYtAccountSheet(context),
        child: acc.signedIn
            ? Container(
