  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge([
        appState,
        audioHandler.libraryRevision,
        audioHandler.currentIndex,
      ]),
      builder: (context, _) {
        final pal = appState.palette;
        final allTracks = audioHandler.tracks;
        final likedTracks =
            allTracks.where((t) => appState.isLiked(t.id)).toList();

        return Scaffold(
          backgroundColor: pal.bg,
          body: Stack(
            children: [
              AuroraPlasmaBackground(
                accent: pal.accent,
                secondary: const Color(0xFFF09CE2),
                intense: true,
              ),
              SafeArea(
                child: Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
                      child: Row(
                        children: [
                          SquishyGesture(
                            onTap: () => Navigator.pop(context),
                            child: Container(
                              width: 44,
                              height: 44,
                              decoration: BoxDecoration(
                                color: pal.surface,
                                shape: BoxShape.circle,
                              ),
                              child: const Icon(
                                Icons.arrow_back_rounded,
                                color: Colors.white,
                              ),
                            ),
                          ),
                          const Spacer(),
                          if (likedTracks.isNotEmpty)
                            SquishyGesture(
                              onTap: () {
                                audioHandler.setShuffleMode(
                                  AudioServiceShuffleMode.all,
                                );
                                final pick = likedTracks[
                                    Random().nextInt(likedTracks.length)];
