class SwipeDownDismiss extends StatefulWidget {
  final Widget child;
  const SwipeDownDismiss({super.key, required this.child});

  @override
  State<SwipeDownDismiss> createState() => _SwipeDownDismissState();
}

class _SwipeDownDismissState extends State<SwipeDownDismiss>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;
  bool _dismissing = false;

  @override
  void initState() {
    super.initState();
    _c = AnimationController.unbounded(vsync: this, value: 0);
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  static const double _upMax = 170;
  bool _openingQueue = false;

  void _update(DragUpdateDetails d) {
    if (_dismissing || _openingQueue) return;
    var dy = d.delta.dy;
    // Pulling up gets heavier the further you go (rubber band).
    if (_c.value < 0 && dy < 0) dy *= 1 - (-_c.value / _upMax) * 0.7;
    final before = _c.value;
    _c.value = (_c.value + dy).clamp(-_upMax, double.infinity).toDouble();
    if (before > -70 && _c.value <= -70) HapticFeedback.selectionClick();
  }

  Future<void> _openQueue(double velocity) async {
    _openingQueue = true;
    HapticFeedback.mediumImpact();
    // Lift the player a little, then the queue slides up over it.
    await _c.animateTo(-_upMax * 0.75,
        duration: const Duration(milliseconds: 120), curve: Curves.easeOut);
    if (!mounted) return;
    final sheet = showQueueSheet(context);
    _springBack(0);
    await sheet;
    _openingQueue = false;
  }

  void _springBack(double velocity) {
    _c.animateWith(
      SpringSimulation(
        const SpringDescription(mass: 1, stiffness: 320, damping: 26),
        _c.value,
        0,
        velocity,
      ),
    );
  }

  void _end(DragEndDetails d) {
    if (_dismissing || _openingQueue) return;
    final v = d.velocity.pixelsPerSecond.dy;
    final h = MediaQuery.of(context).size.height;
    if (_c.value < 0) {
      if (_c.value <= -70 || v < -700) {
        _openQueue(v);
      } else {
        _springBack(v);
      }
      return;
    }
    if (_c.value > h * 0.08 || v > 450) {
      HapticFeedback.lightImpact();
      setState(() => _dismissing = true);
      _c
          .animateTo(
            h,
            duration: const Duration(milliseconds: 260),
            curve: Curves.easeInCubic,
          )
          .whenComplete(() {
        if (mounted) Navigator.of(context).pop();
      });
    } else {
      _springBack(v);
    }
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onVerticalDragUpdate: _update,
      onVerticalDragEnd: _end,
      onVerticalDragCancel: () => _springBack(0),
      child: AnimatedBuilder(
        animation: _c,
        builder: (context, child) {
          final h = MediaQuery.of(context).size.height;
          if (_c.value < 0) {
            // Pulling up: the player lifts, shrinks and rounds off, and an
            // "Up next" hint rises from the bottom.
            final up = (-_c.value / _upMax).clamp(0.0, 1.0).toDouble();
            final pal = appState.palette;
            return Stack(
              children: [
                Transform.translate(
                  offset: Offset(0, _c.value * 0.45),
                  child: child,
                ),
                Positioned(
                  left: 0,
                  right: 0,
                  bottom: 18 + 40 * up,
                  child: IgnorePointer(
                    child: Material(
                      type: MaterialType.transparency,
                      child: Opacity(
                      opacity: up,
                      child: Center(
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 18, vertical: 10),
                          decoration: BoxDecoration(
                            color: Colors.black.withOpacity(0.6),
                            borderRadius: BorderRadius.circular(24),
                            border: Border.all(
                                color: pal.accent.withOpacity(0.5)),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Transform.rotate(
                                angle: -pi / 2 * (1 - up),
                                child: Icon(Icons.keyboard_arrow_up_rounded,
                                    color: pal.accent, size: 22),
                              ),
                              const SizedBox(width: 6),
                              Text(
                                up >= 0.41 ? 'Release for queue' : 'Up next',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.w700,
                                  fontSize: 14,
                                  decoration: TextDecoration.none,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    ),
                  ),
                ),
              ],
            );
          }
          final p = (_c.value / h).clamp(0.0, 1.0).toDouble();
          return Transform.translate(
            offset: Offset(0, _c.value),
            child: Transform.scale(
              scale: 1 - 0.05 * p,
              alignment: Alignment.topCenter,
              child: ClipRRect(
                borderRadius: BorderRadius.circular(min(1.0, p * 8) * 36),
                child: child,
              ),
            ),
          );
        },
        child: HeroMode(
          enabled: !_dismissing,
          child: Stack(
            children: [
              widget.child,
              Positioned(
                left: 0,
                right: 0,
                top: MediaQuery.of(context).padding.top + 64,
                child: const Center(child: CrossfadeTag()),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

Widget _artShuttle(
  BuildContext flightContext,
  Animation<double> animation,
  HeroFlightDirection direction,
  BuildContext fromContext,
  BuildContext toContext,
) {
  return AnimatedBuilder(
    animation: animation,
    builder: (context, _) {
      final t = direction == HeroFlightDirection.push
          ? animation.value
          : 1 - animation.value;
      final track = audioHandler.currentTrack;
      final e = Curves.easeInOutCubic.transform(t.clamp(0.0, 1.0));
      final target = appState.vinylSpinMode ? 999.0 : 28.0;
      return LayoutBuilder(builder: (context, c) {
        final round = c.biggest.shortestSide / 2;
        final r = round + (min(target, round) - round) * e;
        return Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(r),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withOpacity(0.45 * e),
                blurRadius: 30 * e,
                offset: Offset(0, 12 * e),
              ),
            ],
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(r),
            child: track == null
                ? const SizedBox()
                : CustomAlbumArtwork(track: track),
          ),
        );
      });
    },
  );
}

RectTween _arcTween(Rect? begin, Rect? end) =>
    MaterialRectArcTween(begin: begin, end: end);

class SquishyGesture extends StatefulWidget {
  final Widget child;
  final VoidCallback? onTap;
  final double pressedScale;

  const SquishyGesture({
    super.key,
    required this.child,
    this.onTap,
    this.pressedScale = 0.88,
  });

  @override
  State<SquishyGesture> createState() => _SquishyGestureState();
}

class _SquishyGestureState extends State<SquishyGesture>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;
  DateTime _downAt = DateTime.now();

  @override
  void initState() {
    super.initState();
    _c = AnimationController.unbounded(vsync: this, value: 1.0);
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  void _down() {
    _downAt = DateTime.now();
    _c.animateTo(
      widget.pressedScale,
      duration: const Duration(milliseconds: 110),
      curve: Curves.easeOutCubic,
    );
  }

  void _release() {
    if (!mounted) return;
    _c.animateWith(
      SpringSimulation(
        const SpringDescription(mass: 1, stiffness: 380, damping: 13),
        _c.value,
        1.0,
        0.0,
      ),
    );
  }

  void _up() {
    final elapsed = DateTime.now().difference(_downAt).inMilliseconds;
    final wait = max(0, 90 - elapsed);
    if (wait == 0) {
      _release();
    } else {
      Future.delayed(Duration(milliseconds: wait), _release);
    }
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTapDown: (_) => _down(),
      onTapUp: (_) {
        HapticFeedback.lightImpact();
        widget.onTap?.call();
        _up();
      },
      onTapCancel: _up,
      child: AnimatedBuilder(
        animation: _c,
        builder: (context, child) => Transform.scale(
          scale: _c.value.clamp(0.5, 1.15).toDouble(),
          child: child,
        ),
        child: widget.child,
      ),
    );
  }
}

