class NowPlayingScreen extends StatelessWidget {
  const NowPlayingScreen({super.key});

  /// Smooth crossfade when double-tap switches to/from big artwork.
  static Widget _artModeSwitch(Widget player) => AnimatedSwitcher(
        duration: const Duration(milliseconds: 320),
        switchInCurve: Curves.easeOut,
        switchOutCurve: Curves.easeIn,
        child: KeyedSubtree(
          key: ValueKey(appState.b('immersive_art')),
          child: player,
        ),
      );

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge([
        appState,
        audioHandler.libraryRevision,
        audioHandler.currentIndex,
      ]),
      builder: (context, _) {
        final pal = appState.palette;
        final track = audioHandler.currentTrack;
        if (track == null) {
          return Scaffold(backgroundColor: pal.playerBg);
        }
        return StreamBuilder<PlaybackState>(
          stream: audioHandler.playbackState,
          builder: (context, snap) {
            final state = snap.data ?? audioHandler.playbackState.value;
            final playing = state.playing;
            final loading =
                state.processingState == AudioProcessingState.loading;
            final shuffle = state.shuffleMode == AudioServiceShuffleMode.all;
            final repeat = state.repeatMode;
            final liked = appState.isLiked(track.id);

            if (appState.playerStyle == 'modern') {
              return SwipeDownDismiss(
                child: ModernPlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                ),
              );
            }
            if (appState.playerStyle == 'alex') {
              return SwipeDownDismiss(
                child: _artModeSwitch(AlexPlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                )),
              );
            }
            if (appState.playerStyle == 'expressive') {
              return SwipeDownDismiss(
                child: ExpressivePlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                ),
              );
            }
            if (appState.playerStyle == 'simp') {
              return SwipeDownDismiss(
                child: _artModeSwitch(SimpPlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                )),
              );
            }
            if (appState.playerStyle == 'plus') {
              return SwipeDownDismiss(
                child: _artModeSwitch(PlusPlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                )),
              );
            }
            if (appState.playerStyle == 'apple') {
              return SwipeDownDismiss(
                child: AmPlayerView(
                  track: track,
                  playing: playing,
                  loading: loading,
                  shuffle: shuffle,
                  repeat: repeat,
                  liked: liked,
                ),
              );
            }

            return SwipeDownDismiss(
              child: Scaffold(
                backgroundColor: pal.playerBg,
                body: Stack(
                  children: [
                    if (appState.artBackdrop)
                      Positioned.fill(child: AlbumArtBackdrop(track: track)),
                    AuroraPlasmaBackground(
                      accent: pal.accent,
                      secondary: track.artColors.first,
                      intense: true,
                    ),
                    SafeArea(
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 22),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const SizedBox(height: 8),
                            Row(
                              children: [
                                SquishyGesture(
                                  onTap: () => Navigator.of(context).pop(),
                                  child: LiquidGlassBox(
                                    borderRadius: BorderRadius.circular(23),
                                    fallbackColor: pal.playerSurface,
                                    child: const SizedBox(
                                      width: 46,
                                      height: 46,
                                      child: Icon(
                                        Icons.keyboard_arrow_down_rounded,
                                        color: Colors.white,
                                        size: 28,
                                      ),
                                    ),
                                  ),
                                ),
                                Expanded(
                                  child: Padding(
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 8,
                                    ),
                                    child: Column(
                                      children: [
                                        const Text(
                                          'NOW PLAYING',
                                          style: TextStyle(
                                            color: Color(0xFFE5DDD9),
                                            fontSize: 11,
                                            fontWeight: FontWeight.w700,
                                            letterSpacing: 1.0,
                                          ),
                                        ),
                                        const SizedBox(height: 2),
                                        Text(
                                          track.album,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: const TextStyle(
                                            color: Colors.white,
                                            fontSize: 15.5,
                                            fontWeight: FontWeight.w800,
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                                SquishyGesture(
                                  onTap: () =>
                                      showEditTrackDialog(context, track),
                                  child: LiquidGlassBox(
                                    borderRadius: BorderRadius.circular(16),
                                    fallbackColor: pal.playerSurface,
                                    child: const SizedBox(
                                      width: 44,
                                      height: 44,
                                      child: Icon(
                                        Icons.edit_rounded,
                                        color: Colors.white,
                                        size: 20,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                SquishyGesture(
                                  onTap: () =>
                                      showAddToPlaylistSheet(context, track),
                                  child: LiquidGlassBox(
