                    valueListenable: OfflineStore.revision,
                    builder: (_, __, ___) {
                      final saved = OfflineStore.isDownloaded(track);
                      final busy = OfflineStore.isBusy(track);
                      return _menuAction(
                        pal,
                        saved
                            ? Icons.download_done_rounded
                            : Icons.download_for_offline_rounded,
                        saved
                            ? 'Remove download'
                            : busy
