// ═══════════════════════ Sound presets & reverb ═══════════════════════

class SoundPreset {
  final String name;
  final IconData icon;
  final double speed;
  final double pitch;
  final double reverb;
  const SoundPreset(this.name, this.icon, this.speed, this.pitch, this.reverb);
}

const List<SoundPreset> kSoundPresets = [
  SoundPreset('Normal', Icons.music_note_rounded, 1.0, 1.0, 0.0),
  // Faster and higher together, like the TikTok "sped up" edits.
  SoundPreset('Sped Up', Icons.fast_forward_rounded, 1.2, 1.2, 0.0),
  // Slower and deeper together.
  SoundPreset('Slowed Down', Icons.slow_motion_video_rounded, 0.85, 0.85, 0.0),
  // Classic nightcore: much faster, pitched up a bit more (~+5 semitones).
  SoundPreset('Nightcore', Icons.bolt_rounded, 1.3, 1.35, 0.0),
  // Slowed + a big washy room.
  SoundPreset('Slowed & Reverb', Icons.waves_rounded, 0.8, 0.8, 0.55),
];

/// Sends the reverb amount (Settings value 0..1) to Android's reverb effect.
Future<void> applyReverb({bool quiet = false}) async {
  if (!Platform.isAndroid) return;
  final level = appState.d('reverb', 0.0);
  final session = audioHandler.player.androidAudioSessionId ?? 0;
  try {
    await _mediaChannel
        .invokeMethod('setReverb', {'session': session, 'level': level});
  } catch (e) {
    if (!quiet && level > 0) {
      final detail = e is PlatformException ? (e.message ?? e.code) : '$e';
      appNotice.value = 'Reverb isn\'t available on this phone: $detail';
    }
  }
}

void setReverbLevel(double v, {bool quiet = false}) {
  appState.setD('reverb', v.clamp(0.0, 1.0).toDouble());
  applyReverb(quiet: quiet);
}

void applySoundPreset(SoundPreset p) {
  HapticFeedback.selectionClick();
  appState.setLinkSpeedAndPitch((p.speed - p.pitch).abs() < 0.001);
  appState.setSpeed(p.speed);
  appState.setPitch(p.pitch);
  audioHandler.setSpeed(p.speed);
  audioHandler.setPitch(p.pitch);
  setReverbLevel(p.reverb);
}

SoundPreset? currentSoundPreset() {
  for (final p in kSoundPresets) {
    if ((appState.speed - p.speed).abs() < 0.01 &&
        (appState.pitch - p.pitch).abs() < 0.01 &&
        (appState.d('reverb', 0.0) - p.reverb).abs() < 0.02) {
      return p;
    }
  }
  return null;
}

/// True when speed, pitch or reverb differ from normal (to light up buttons).
bool get soundModified =>
    appState.speed != 1.0 ||
    appState.pitch != 1.0 ||
    appState.d('reverb', 0.0) > 0.001;

void showPlaybackSheet(BuildContext context) {
  _sheet(
    context,
    (ctx) => ListenableBuilder(
      listenable: appState,
      builder: (ctx, _) {
        final pal = appState.palette;
        final semitones = (12 * (log(appState.pitch) / ln2)).round();
        final preset = currentSoundPreset();
        final reverb = appState.d('reverb', 0.0);
        return SafeArea(
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    const Text(
                      'Speed, Pitch & Reverb',
                      style: TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.w800,
                        color: Colors.white,
                      ),
                    ),
                    SquishyGesture(
                      onTap: () => applySoundPreset(kSoundPresets.first),
                      child: Padding(
                        padding: const EdgeInsets.all(8),
                        child: Text(
                          'Reset',
                          style: TextStyle(
                            color: pal.accent,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                const Text(
                  'PRESETS',
                  style: TextStyle(
                    color: Colors.white54,
                    fontSize: 11.5,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 0.8,
                  ),
                ),
                const SizedBox(height: 8),
                SizedBox(
                  height: 86,
                  child: ListView.separated(
                    scrollDirection: Axis.horizontal,
                    itemCount: kSoundPresets.length,
                    separatorBuilder: (_, __) => const SizedBox(width: 10),
                    itemBuilder: (_, i) {
                      final p = kSoundPresets[i];
                      final on = identical(preset, p);
                      return SquishyGesture(
                        pressedScale: 0.93,
                        onTap: () => applySoundPreset(p),
                        child: AnimatedContainer(
                          duration: const Duration(milliseconds: 220),
                          width: 96,
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: on ? pal.accent : pal.playerButton,
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(
                              color: on ? pal.accent : Colors.white12,
                            ),
                          ),
                          child: Column(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              Icon(p.icon,
                                  color: on ? pal.onAccent : Colors.white,
                                  size: 26),
                              const SizedBox(height: 6),
                              Text(
                                p.name,
                                maxLines: 2,
                                textAlign: TextAlign.center,
                                style: TextStyle(
                                  color: on ? pal.onAccent : Colors.white,
                                  fontSize: 12,
                                  height: 1.1,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                ),
                const SizedBox(height: 8),
                SwitchListTile(
                  contentPadding: EdgeInsets.zero,
                  dense: true,
                  title: const Text(
                    'Change speed & pitch together',
                    style: TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.w700,
                      fontSize: 13.5,
                    ),
                  ),
                  subtitle: const Text(
                    'Shifts pitch & tempo together like a real turntable',
                    style: TextStyle(color: Colors.white60, fontSize: 12),
                  ),
                  value: appState.linkSpeedAndPitch,
                  activeColor: pal.accent,
                  onChanged: (v) {
                    appState.setLinkSpeedAndPitch(v);
                    if (v) {
                      appState.setSpeed(appState.pitch);
                      audioHandler.setSpeed(appState.pitch);
                    }
                  },
                ),
                const SizedBox(height: 6),
                Text(
                  'Speed: ${appState.speed.toStringAsFixed(2)}x',
                  style: const TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                Slider(
                  value: appState.speed.clamp(0.5, 2.0),
                  min: 0.5,
                  max: 2.0,
                  divisions: 30,
                  activeColor: pal.accent,
                  onChanged: (v) {
                    appState.setSpeed(v);
                    audioHandler.setSpeed(v);
                    if (appState.linkSpeedAndPitch) {
                      appState.setPitch(v);
                      audioHandler.setPitch(v);
                    }
                  },
                ),
                const SizedBox(height: 6),
                Text(
                  'Pitch: ${appState.pitch.toStringAsFixed(2)}x  (${semitones >= 0 ? '+$semitones' : '$semitones'} semitones)',
                  style: const TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                Slider(
                  value: appState.pitch.clamp(0.5, 2.0),
                  min: 0.5,
                  max: 2.0,
                  divisions: 60,
                  activeColor: pal.accent,
                  onChanged: (v) {
                    appState.setPitch(v);
                    audioHandler.setPitch(v);
                    if (appState.linkSpeedAndPitch) {
                      appState.setSpeed(v);
                      audioHandler.setSpeed(v);
                    }
                  },
                ),
                const SizedBox(height: 8),
                Wrap(
                  spacing: 8,
                  children: [-6, -3, -1, 0, 1, 3, 6].map((st) {
                    final targetPitch = pow(2.0, st / 12.0).toDouble();
                    final active = (appState.pitch - targetPitch).abs() < 0.02;
                    return ChoiceChip(
                      label: Text(
                        st == 0 ? '0 st' : (st > 0 ? '+$st st' : '$st st'),
                      ),
                      selected: active,
                      showCheckmark: false,
                      selectedColor: pal.accent,
                      backgroundColor: pal.playerButton,
                      labelStyle: TextStyle(
                        color: active ? pal.onAccent : Colors.white,
                        fontWeight: FontWeight.w700,
                      ),
                      onSelected: (_) {
                        appState.setPitch(targetPitch);
                        audioHandler.setPitch(targetPitch);
                        if (appState.linkSpeedAndPitch) {
                          appState.setSpeed(targetPitch);
                          audioHandler.setSpeed(targetPitch);
                        }
                      },
                    );
                  }).toList(),
                ),
                const SizedBox(height: 14),
                Row(
                  children: [
                    const Icon(Icons.waves_rounded,
                        color: Colors.white70, size: 20),
                    const SizedBox(width: 8),
                    Text(
                      'Reverb: ${reverb <= 0.001 ? 'Off' : '${(reverb * 100).round()}%'}',
                      style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
                Slider(
                  value: reverb.clamp(0.0, 1.0),
                  min: 0,
                  max: 1,
                  divisions: 20,
                  activeColor: pal.accent,
                  onChanged: (v) => appState.setD('reverb', v),
                  onChangeEnd: (v) => setReverbLevel(v),
                ),
                const Text(
                  'Reverb uses your phone\'s built-in audio effects, so how it sounds can vary between phones.',
                  style: TextStyle(color: Colors.white54, fontSize: 12),
                ),
              ],
            ),
          ),
        );
      },
    ),
    color: appState.palette.playerSurface,
  );
}

/// The queue's contents (Up next + the rest), shared by the queue screen.
Widget _queueBody() => ListenableBuilder(
    listenable: Listenable.merge([
      audioHandler.libraryRevision,
      audioHandler.currentIndex,
      audioHandler.upNextRevision,
      appState,
    ]),
    builder: (ctx, _) {
      final pal = appState.palette;
      final tracks = audioHandler.tracks;
      final upNext = audioHandler.upNext;
      Widget label(String text) => Padding(
            padding: const EdgeInsets.fromLTRB(2, 10, 2, 6),
            child: Text(
              text,
              style: const TextStyle(
                color: Colors.white54,
                fontSize: 12,
                fontWeight: FontWeight.w800,
                letterSpacing: 0.9,
              ),
            ),
          );
      final upNextSection = Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(child: label('UP NEXT (${upNext.length})')),
              if (upNext.isNotEmpty)
                TextButton.icon(
                  onPressed: () {
                    HapticFeedback.mediumImpact();
                    audioHandler.clearQueue();
                  },
                  icon: const Icon(Icons.clear_all_rounded, size: 20),
                  label: const Text('Clear queue'),
                  style: TextButton.styleFrom(foregroundColor: pal.accent),
                ),
            ],
          ),
          if (upNext.isEmpty)
            const Padding(
              padding: EdgeInsets.only(bottom: 6),
              child: Text(
                'Nothing queued. Use "Play next" or "Add to queue" in a song\'s ⋮ menu.',
                style: TextStyle(color: Colors.white38, fontSize: 13),
              ),
            ),
          for (var q = 0; q < upNext.length; q++)
            ListTile(
              key: ValueKey('up_${q}_${upNext[q].id}'),
              contentPadding: EdgeInsets.zero,
              leading: ClipRRect(
                borderRadius: BorderRadius.circular(8),
                child: SizedBox(
                  width: 44,
                  height: 44,
                  child: CustomAlbumArtwork(track: upNext[q]),
                ),
              ),
              title: Text(
                upNext[q].title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: Colors.white, fontWeight: FontWeight.w700),
              ),
              subtitle: Text(
                upNext[q].artist,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Colors.white70),
              ),
              trailing: IconButton(
                icon: const Icon(Icons.close_rounded, color: Colors.white54),
                onPressed: () => audioHandler.removeFromQueue(q),
              ),
            ),
          label('THEN FROM YOUR LIBRARY'),
        ],
      );
      return Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        child: Column(
          children: [
            const Text(
              'Queue',
              style: TextStyle(
                color: Colors.white,
                fontSize: 18,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 4),
            Expanded(
              child: ReorderableListView.builder(
                header: upNextSection,
                buildDefaultDragHandles: false,
                itemCount: tracks.length,
                onReorder: (oldIndex, newIndex) {
                  if (newIndex > oldIndex) newIndex -= 1;
                  audioHandler.moveTrack(oldIndex, newIndex);
                },
                itemBuilder: (_, i) {
                  final t = tracks[i];
                  final active = i == audioHandler.index;
                  return ListTile(
                    key: ValueKey(t.id),
                    contentPadding: EdgeInsets.zero,
                    leading: ClipRRect(
                      borderRadius: BorderRadius.circular(8),
                      child: SizedBox(
                        width: 44,
                        height: 44,
                        child: CustomAlbumArtwork(track: t),
                      ),
                    ),
                    title: Text(
                      t.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: active ? pal.accent : Colors.white,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    subtitle: Text(
                      t.artist,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(color: Colors.white70),
                    ),
                    trailing: ReorderableDragStartListener(
                      index: i,
                      child: const Icon(
                        Icons.drag_handle_rounded,
                        color: Colors.white54,
                      ),
                    ),
                    onTap: () => audioHandler.playIndex(i),
                  );
                },
              ),
            ),
          ],
        ),
      );
    },
  );

/// Opens the queue full screen, sliding up over the player.
Future<void> showQueueSheet(BuildContext context) {
  return Navigator.of(context).push(PageRouteBuilder<void>(
    transitionDuration: const Duration(milliseconds: 420),
    reverseTransitionDuration: const Duration(milliseconds: 300),
    pageBuilder: (_, __, ___) => const QueueScreen(),
    transitionsBuilder: (_, anim, __, child) {
      final c = CurvedAnimation(
          parent: anim, curve: kEmphasizedDecel, reverseCurve: kEmphasizedAccel);
      return SlideTransition(
        position: Tween<Offset>(begin: const Offset(0, 1), end: Offset.zero)
            .animate(c),
        child: child,
      );
    },
  ));
}

/// True-black background with soft colour glows drifting slowly: your theme
/// colour plus the current song's colour. Plain gradients, no blur.
class AmoledGlow extends StatefulWidget {
  final Color accent;
  const AmoledGlow({super.key, required this.accent});

  @override
  State<AmoledGlow> createState() => _AmoledGlowState();
}

class _AmoledGlowState extends State<AmoledGlow>
    with SingleTickerProviderStateMixin {
  late final AnimationController _t = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 32),
  )..repeat();

  @override
  void dispose() {
    _t.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final track = audioHandler.currentTrack;
    return FutureBuilder<Color>(
      future: track == null ? null : artSeedFor(track),
      builder: (context, snap) {
        final song = snap.data ?? track?.artColors.first ?? widget.accent;
        return IgnorePointer(
          child: RepaintBoundary(
            child: AnimatedBuilder(
              animation: _t,
              builder: (context, _) => CustomPaint(
                painter: _GlowPainter(_t.value, widget.accent, song),
              ),
            ),
          ),
        );
      },
    );
  }
}

class _GlowPainter extends CustomPainter {
  final double t;
  final Color a;
  final Color b;
  _GlowPainter(this.t, this.a, this.b);

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Offset.zero & size, Paint()..color = Colors.black);
    final w = size.width, h = size.height;
    final ang = t * 2 * pi;
    void glow(Offset c, double r, Color col, double o) {
      canvas.drawCircle(
        c,
        r,
        Paint()
          ..shader = RadialGradient(
            colors: [col.withOpacity(o), col.withOpacity(0)],
          ).createShader(Rect.fromCircle(center: c, radius: r)),
      );
    }

    glow(Offset(w * (0.15 + 0.2 * sin(ang)), h * (0.12 + 0.06 * cos(ang * 1.3))),
        w * 0.9, a, 0.30);
    glow(Offset(w * (0.9 + 0.12 * cos(ang * 0.8)), h * (0.55 + 0.1 * sin(ang))),
        w * 0.85, b, 0.26);
    glow(Offset(w * (0.3 + 0.2 * cos(ang * 1.2)), h * (1.0 + 0.04 * sin(ang * 0.7))),
        w * 0.8, Color.lerp(a, b, 0.5)!, 0.18);
  }

  @override
  bool shouldRepaint(covariant _GlowPainter old) =>
      old.t != t || old.a != a || old.b != b;
}

class QueueScreen extends StatefulWidget {
  const QueueScreen({super.key});

  @override
  State<QueueScreen> createState() => _QueueScreenState();
}

class _QueueScreenState extends State<QueueScreen> {
  double _drag = 0;
  bool _closing = false;

  void _close() {
    if (_closing) return;
    _closing = true;
    Navigator.of(context).pop();
  }

  /// Pulling down when the list is already at the top drags the queue down;
  /// let go far enough (or flick) and it closes, back to the player.
  bool _onScroll(ScrollNotification n) {
    if (_closing || n.metrics.axis != Axis.vertical) return false;
    if (n is OverscrollNotification &&
        n.dragDetails != null &&
        n.overscroll < 0 &&
        n.metrics.extentBefore == 0) {
      setState(() => _drag = _drag - n.overscroll);
    } else if (n is ScrollUpdateNotification &&
        _drag > 0 &&
        n.dragDetails != null &&
        (n.scrollDelta ?? 0) > 0) {
      setState(() => _drag = max(0, _drag - (n.scrollDelta ?? 0)));
    } else if (n is ScrollEndNotification && _drag > 0) {
      final v = n.dragDetails?.velocity.pixelsPerSecond.dy ?? 0;
      if (_drag > 90 || v > 600) {
        _close();
      } else {
        setState(() => _drag = 0);
      }
    }
    return false;
  }

  @override
  Widget build(BuildContext context) {
    final pal = appState.palette;
    // Drag the top bar down (or flick it) to go back to the player.
    final handle = GestureDetector(
      behavior: HitTestBehavior.opaque,
      onVerticalDragUpdate: (d) =>
          setState(() => _drag = max(0, _drag + d.delta.dy)),
      onVerticalDragEnd: (d) {
        if (_drag > 90 || d.velocity.pixelsPerSecond.dy > 600) {
          _close();
        } else {
          setState(() => _drag = 0);
        }
      },
      child: Padding(
        padding: const EdgeInsets.fromLTRB(8, 6, 8, 2),
        child: Column(
          children: [
            Container(
              width: 40,
              height: 5,
              decoration: BoxDecoration(
                color: Colors.white30,
                borderRadius: BorderRadius.circular(3),
              ),
            ),
            Row(
              children: [
                IconButton(
                  icon: const Icon(Icons.keyboard_arrow_down_rounded,
                      color: Colors.white, size: 30),
                  onPressed: () => Navigator.of(context).pop(),
                ),
              ],
            ),
          ],
        ),
      ),
    );
    return AnimatedContainer(
      duration: _drag == 0 ? const Duration(milliseconds: 220) : Duration.zero,
      curve: Curves.easeOutCubic,
      transform: Matrix4.translationValues(0, _drag, 0),
      child: Scaffold(
        backgroundColor: Colors.black,
        body: Stack(
          fit: StackFit.expand,
          children: [
            AmoledGlow(accent: pal.accent),
            SafeArea(
              child: Column(
                children: [
                  handle,
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 18),
                      child: NotificationListener<ScrollNotification>(
                        onNotification: _onScroll,
                        child: _queueBody(),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

