/// Full-screen search. Type to see quick matches from your library; press
/// Enter for full results, then switch between Local and YouTube Music
/// (with Songs / Albums / Artists filters).
class SearchScreen extends StatefulWidget {
  final String? initialQuery;
  const SearchScreen({super.key, this.initialQuery});

  @override
  State<SearchScreen> createState() => _SearchScreenState();
}

class _SearchScreenState extends State<SearchScreen> {
  final TextEditingController _ctrl = TextEditingController();
  final FocusNode _focus = FocusNode();
  String _query = '';
  String? _submitted; // results mode when set
  // YouTube Music first (like YouTube Music clients); Local is one tap away.
  int _source = appState.b('search_yt_default', true) ? 1 : 0; // 0 local, 1 YouTube
  int _filter = 0; // 0 songs, 1 albums, 2 artists

  // YouTube results for the submitted query (cached per filter).
  Future<List<TrackItem>>? _ytSongs;
  Future<List<YtAlbum>>? _ytAlbums;
  Future<List<YtArtist>>? _ytArtists;

  @override
  void initState() {
    super.initState();
    final q = widget.initialQuery;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (q != null && q.trim().isNotEmpty) {
        _ctrl.text = q;
        _submit(q);
      } else {
        _focus.requestFocus();
      }
    });
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _focus.dispose();
    super.dispose();
  }

  List<String> get _history {
    try {
      return YouTubeMusic.prefs?.getStringList('search_history') ?? const [];
    } catch (_) {
      return const [];
    }
  }

  void _remember(String q) {
    if (!appState.b('search_history_on', true)) return;
    final list = [q, ..._history.where((x) => x.toLowerCase() != q.toLowerCase())]
        .take(12)
        .toList();
    YouTubeMusic.prefs?.setStringList('search_history', list);
  }

  void _submit(String raw) {
    final q = raw.trim();
    if (q.isEmpty) return;
    _remember(q);
    _focus.unfocus();
    setState(() {
      _submitted = q;
      _query = q;
      _ytSongs = null;
      _ytAlbums = null;
      _ytArtists = null;
      // No local matches? Show YouTube Music.
      if (_localSongs(q).isEmpty && Platform.isAndroid) _source = 1;
    });
  }

  void _edit() {
    setState(() => _submitted = null);
    _focus.requestFocus();
  }

  List<TrackItem> _localSongs(String q) {
    final l = q.toLowerCase();
    return audioHandler.tracks
        .where((t) =>
            t.title.toLowerCase().contains(l) ||
            t.artist.toLowerCase().contains(l) ||
            t.album.toLowerCase().contains(l))
        .toList();
  }

  void _playLocal(TrackItem t) {
    final idx = audioHandler.tracks.indexOf(t);
    if (idx >= 0) playAndOpen(context, idx);
  }

  void _playYt(TrackItem t) {
    audioHandler.playYouTubeTrack(t);
    openPlayer(context);
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge([appState, audioHandler.currentIndex]),
      builder: (context, _) {
        final pal = appState.palette;
        return Scaffold(
          backgroundColor: pal.bg,
          body: SafeArea(
            child: Column(
              children: [
                _searchBar(pal),
                Expanded(
                  child: AnimatedSwitcher(
                    duration: const Duration(milliseconds: 220),
                    child: _submitted == null
                        ? KeyedSubtree(
                            key: const ValueKey('typing'),
                            child: _typing(pal),
                          )
                        : KeyedSubtree(
                            key: ValueKey('results_$_submitted'),
                            child: _results(pal),
                          ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _searchBar(AppPalette pal) {
    final community = appState.community;
    return Padding(
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 6),
      child: Container(
        height: 56,
        decoration: BoxDecoration(
          color: community ? appState.scheme.surfaceContainerHigh : pal.surface,
          borderRadius: BorderRadius.circular(28),
          border: community ? null : Border.all(color: Colors.white10),
        ),
        child: Row(
          children: [
            IconButton(
              icon: const Icon(Icons.arrow_back_rounded),
              onPressed: () => Navigator.pop(context),
            ),
            Expanded(
              child: TextField(
                controller: _ctrl,
                focusNode: _focus,
                readOnly: _submitted != null,
                onTap: _submitted != null ? _edit : null,
                textInputAction: TextInputAction.search,
                style: const TextStyle(color: Colors.white, fontSize: 16.5),
                decoration: const InputDecoration(
                  hintText: 'Songs, artists, albums…',
                  hintStyle: TextStyle(color: Colors.white54),
                  border: InputBorder.none,
                ),
                onChanged: (v) => setState(() => _query = v),
                onSubmitted: _submit,
              ),
            ),
            if (_query.isNotEmpty)
              IconButton(
                icon: const Icon(Icons.close_rounded),
                onPressed: () {
                  _ctrl.clear();
                  setState(() {
                    _query = '';
                    _submitted = null;
                  });
                  _focus.requestFocus();
                },
              )
            else
              Padding(
                padding: const EdgeInsets.only(right: 16),
                child: Icon(Icons.search_rounded, color: pal.accent),
              ),
          ],
        ),
      ),
    );
  }

  // ── While typing ───────────────────────────────────────────────────────

  Widget _typing(AppPalette pal) {
    final q = _query.trim();
    if (q.isEmpty) {
      final history =
          appState.b('search_history_on', true) ? _history : const <String>[];
      return ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 40),
        children: [
          if (history.isEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 60),
              child: Column(
                children: [
                  Icon(Icons.manage_search_rounded, size: 64, color: pal.accent),
                  const SizedBox(height: 12),
                  const Text(
                    'Search your music and YouTube Music',
                    style: TextStyle(color: Colors.white70, fontSize: 16),
                  ),
                ],
              ),
            )
          else ...[
            Row(
              children: [
                const Expanded(
                  child: Text('Recent searches',
                      style: TextStyle(
                          color: Colors.white,
                          fontSize: 17,
                          fontWeight: FontWeight.w800)),
                ),
                TextButton(
                  onPressed: () {
                    YouTubeMusic.prefs?.remove('search_history');
                    setState(() {});
                  },
                  child: const Text('Clear all'),
                ),
              ],
            ),
            for (final h in history)
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.history_rounded, color: Colors.white54),
                title: Text(h, style: const TextStyle(color: Colors.white)),
                trailing: const Icon(Icons.north_west_rounded,
                    color: Colors.white38, size: 20),
                onTap: () {
                  _ctrl.text = h;
                  _submit(h);
                },
              ),
          ],
        ],
      );
    }

    final local = _localSongs(q).take(6).toList();
    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 4, 16, 40),
      children: [
        _suggestRow(pal, Icons.search_rounded, 'Search for "$q"',
            'Your library and YouTube Music', () => _submit(q)),
        if (Platform.isAndroid)
          _suggestRow(pal, Icons.play_circle_fill_rounded, 'YouTube Music',
              'Songs, albums and artists for "$q"', () {
            _source = 1;
            _submit(q);
          }),
        if (local.isNotEmpty) ...[
          const Padding(
            padding: EdgeInsets.fromLTRB(2, 16, 2, 6),
            child: Text('IN YOUR LIBRARY',
                style: TextStyle(
                    color: Colors.white54,
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.9)),
          ),
          for (final t in local)
            TrackRow(
              track: t,
              palette: pal,
              active: audioHandler.currentTrack?.id == t.id,
              onTap: () => _playLocal(t),
              onMore: () => showAddToPlaylistSheet(context, t),
            ),
        ],
      ],
    );
  }

  Widget _suggestRow(AppPalette pal, IconData icon, String title, String sub,
      VoidCallback onTap) {
    return ListTile(
      contentPadding: EdgeInsets.zero,
      leading: Container(
        width: 44,
        height: 44,
        decoration: BoxDecoration(color: pal.container, shape: BoxShape.circle),
        child: Icon(icon, color: pal.accent),
      ),
      title: Text(title,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w700)),
      subtitle: Text(sub, style: const TextStyle(color: Colors.white54)),
      onTap: onTap,
    );
  }

  // ── Results ────────────────────────────────────────────────────────────

  Widget _results(AppPalette pal) {
    final q = _submitted!;
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 6, 16, 4),
          child: SizedBox(
            width: double.infinity,
            child: SegmentedButton<int>(
              segments: [
                const ButtonSegment(
                  value: 0,
                  icon: Icon(Icons.library_music_rounded),
                  label: Text('Local'),
                ),
                if (Platform.isAndroid)
                  const ButtonSegment(
                    value: 1,
                    icon: Icon(Icons.play_circle_fill_rounded),
                    label: Text('YouTube Music'),
                  ),
              ],
              selected: {_source},
              showSelectedIcon: false,
              onSelectionChanged: (v) => setState(() => _source = v.first),
            ),
          ),
        ),
        if (_source == 1)
          SizedBox(
            height: 48,
            child: ListView(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
              children: [
                for (final (i, label, icon) in const [
                  (0, 'Songs', Icons.music_note_rounded),
                  (1, 'Albums', Icons.album_rounded),
                  (2, 'Artists', Icons.person_rounded),
                ])
                  Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: FilterChip(
                      selected: _filter == i,
                      showCheckmark: false,
                      avatar: Icon(icon, size: 18),
                      label: Text(label),
                      onSelected: (_) => setState(() => _filter = i),
                    ),
                  ),
              ],
            ),
          ),
        Expanded(
          child: _source == 0 ? _localResults(pal, q) : _ytResults(pal, q),
        ),
      ],
    );
  }

  Widget _empty(String text) => Padding(
        padding: const EdgeInsets.only(top: 60),
        child: Center(
          child: Text(text,
              textAlign: TextAlign.center,
              style: const TextStyle(color: Colors.white54, fontSize: 15)),
        ),
      );

  Widget _localResults(AppPalette pal, String q) {
    final songs = _localSongs(q);
    final l = q.toLowerCase();
    final artists = <String, List<TrackItem>>{};
    final albums = <String, List<TrackItem>>{};
    for (final t in audioHandler.tracks) {
      if (t.artist.toLowerCase().contains(l)) {
        artists.putIfAbsent(t.artist, () => []).add(t);
      }
      if (t.album.toLowerCase().contains(l)) {
        albums.putIfAbsent(t.album, () => []).add(t);
      }
    }
    if (songs.isEmpty && artists.isEmpty && albums.isEmpty) {
      return ListView(children: [
        _empty('Nothing in your library matches "$q".\nTry YouTube Music above.'),
      ]);
    }
    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 4, 16, 40),
      children: [
        if (artists.isNotEmpty) ...[
          ytSectionHeader('Artists'),
          SizedBox(
            height: 120,
            child: ListView(
              scrollDirection: Axis.horizontal,
              children: [
                for (final e in artists.entries)
                  Padding(
                    padding: const EdgeInsets.only(right: 14),
                    child: SquishyGesture(
                      onTap: () => showArtistTracksSheet(context, e.key, e.value),
                      child: SizedBox(
                        width: 86,
                        child: Column(
                          children: [
                            ClipOval(
                              child: SizedBox(
                                width: 80,
                                height: 80,
                                child: CustomAlbumArtwork(track: e.value.first),
                              ),
                            ),
                            const SizedBox(height: 6),
                            Text(e.key,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 12.5,
                                    fontWeight: FontWeight.w600)),
                          ],
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ],
        if (albums.isNotEmpty) ...[
          ytSectionHeader('Albums'),
          SizedBox(
            height: 186,
            child: ListView(
              scrollDirection: Axis.horizontal,
              children: [
                for (final e in albums.entries)
                  Padding(
                    padding: const EdgeInsets.only(right: 14),
                    child: MediaCard(
                      width: 130,
                      cover: CustomAlbumArtwork(track: e.value.first),
                      title: e.key,
                      subtitle: e.value.first.artist,
                      onTap: () => showArtistTracksSheet(context, e.key, e.value),
                    ),
                  ),
              ],
            ),
          ),
        ],
        if (songs.isNotEmpty) ...[
          ytSectionHeader('Songs (${songs.length})'),
          for (final t in songs)
            TrackRow(
              track: t,
              palette: pal,
              active: audioHandler.currentTrack?.id == t.id,
              onTap: () => _playLocal(t),
              onMore: () => showAddToPlaylistSheet(context, t),
            ),
        ],
      ],
    );
  }

  Widget _ytError(Object? e) {
    final detail = e is PlatformException ? (e.message ?? e.code) : '$e';
    return ListView(children: [
      Padding(
        padding: const EdgeInsets.all(24),
        child: SelectableText(
          'Couldn\'t reach YouTube Music.\n\nDetails: $detail',
          style: const TextStyle(color: Colors.white54),
        ),
      ),
    ]);
  }

  Widget _loading(AppPalette pal) => Padding(
        padding: const EdgeInsets.only(top: 40),
        child: Center(child: CircularProgressIndicator(color: pal.accent)),
      );

  Widget _ytResults(AppPalette pal, String q) {
    switch (_filter) {
      case 1:
        _ytAlbums ??= YouTubeMusic.searchAlbums(q);
        return FutureBuilder<List<YtAlbum>>(
          future: _ytAlbums,
          builder: (context, snap) {
            if (snap.hasError) return _ytError(snap.error);
            if (!snap.hasData) return _loading(pal);
            final list = snap.data!;
            if (list.isEmpty) return ListView(children: [_empty('No albums found.')]);
            final w = (MediaQuery.of(context).size.width - 32 - 14) / 2;
            return ListView(
              padding: const EdgeInsets.fromLTRB(16, 8, 16, 40),
              children: [
                Wrap(
                  spacing: 14,
                  runSpacing: 18,
                  children: [
                    for (final a in list)
                      MediaCard(
                        width: w,
                        cover: YtNetworkImage(url: a.thumbnail, size: w),
                        title: a.title,
                        subtitle: a.artist,
                        onTap: () => openYtAlbum(context, a),
                      ),
                  ],
                ),
              ],
            );
          },
        );
      case 2:
        _ytArtists ??= YouTubeMusic.searchArtists(q);
        return FutureBuilder<List<YtArtist>>(
          future: _ytArtists,
          builder: (context, snap) {
            if (snap.hasError) return _ytError(snap.error);
            if (!snap.hasData) return _loading(pal);
            final list = snap.data!;
            if (list.isEmpty) return ListView(children: [_empty('No artists found.')]);
            return ListView(
              padding: const EdgeInsets.fromLTRB(16, 8, 16, 40),
              children: [
                for (final a in list)
                  ListTile(
                    contentPadding: const EdgeInsets.symmetric(vertical: 4),
                    leading: YtNetworkImage(
                      url: a.thumbnail,
                      size: 56,
                      circle: true,
                      fallbackIcon: Icons.person_rounded,
                    ),
                    title: Text(a.name,
                        style: const TextStyle(
                            color: Colors.white, fontWeight: FontWeight.w700)),
                    subtitle: Text(
                      a.subscribers >= 0
                          ? 'Artist • ${formatCompactCount(a.subscribers)} subscribers'
                          : 'Artist',
                      style: const TextStyle(color: Colors.white54),
                    ),
                    trailing: const Icon(Icons.chevron_right_rounded),
                    onTap: () => openYtArtist(context, a.url, a.name,
                        thumbnail: a.thumbnail),
                  ),
              ],
            );
          },
        );
      default:
        _ytSongs ??= YouTubeMusic.search(q);
        return FutureBuilder<List<TrackItem>>(
          future: _ytSongs,
          builder: (context, snap) {
            if (snap.hasError) return _ytError(snap.error);
            if (!snap.hasData) return _loading(pal);
            final list = snap.data!;
            if (list.isEmpty) return ListView(children: [_empty('No songs found.')]);
            return ListView(
              padding: const EdgeInsets.fromLTRB(16, 8, 16, 40),
              children: [
                for (final t in list)
                  YtTrackRow(track: t, onPlay: () => _playYt(t)),
              ],
            );
          },
        );
    }
  }
}

class SearchSheet extends StatefulWidget {
  final BuildContext parentContext;
  const SearchSheet({super.key, required this.parentContext});

  @override
  State<SearchSheet> createState() => _SearchSheetState();
}

class _SearchSheetState extends State<SearchSheet> {
  static int _lastTab = 0; // 0 = Library, 1 = YouTube Music (kept while app runs)

  String _query = '';
  int _tab = appState.b('search_yt_default') ? 1 : _lastTab;
  final TextEditingController _ctrl = TextEditingController();
  Timer? _debounce;
  int _ytSeq = 0;
  String _ytQuery = '';

  bool _songsLoading = false;
  bool _artistsLoading = false;
  bool _albumsLoading = false;
  String? _songsError;
  List<TrackItem> _songs = const [];
  List<YtArtist> _artists = const [];
  List<YtAlbum> _albums = const [];

  @override
  void dispose() {
    _debounce?.cancel();
    _ctrl.dispose();
    super.dispose();
  }

  // Recent searches (YouTube Music tab).
  List<String> get _history {
    try {
      return YouTubeMusic.prefs?.getStringList('search_history') ?? const [];
    } catch (_) {
      return const [];
    }
  }

  void _remember(String q) {
    if (!appState.b('search_history_on', true)) return;
    final list = [q, ..._history.where((x) => x.toLowerCase() != q.toLowerCase())]
        .take(12)
        .toList();
    YouTubeMusic.prefs?.setStringList('search_history', list);
  }

  void _useHistory(String q) {
    _ctrl.text = q;
    _ctrl.selection = TextSelection.collapsed(offset: q.length);
    setState(() => _query = q);
    _searchYt(q);
  }

  void _setTab(int t) {
    if (t == _tab) return;
    _lastTab = t;
    setState(() => _tab = t);
    final q = _query.trim();
    if (t == 1 && q.length >= 2 && q != _ytQuery) _searchYt(q);
  }

  void _onQueryChanged(String v) {
    setState(() => _query = v);
    _debounce?.cancel();
    final q = v.trim();
    if (q.length < 2) {
      _ytSeq++;
      _ytQuery = '';
      setState(() {
        _songsLoading = _artistsLoading = _albumsLoading = false;
        _songsError = null;
        _songs = const [];
        _artists = const [];
        _albums = const [];
      });
      return;
    }
    if (_tab == 1) {
      _debounce = Timer(const Duration(milliseconds: 450), () => _searchYt(q));
    }
  }

  void _searchYt(String q) {
    final seq = ++_ytSeq;
    _ytQuery = q;
    _remember(q);
    setState(() {
      _songsLoading = _artistsLoading = _albumsLoading = true;
      _songsError = null;
    });
    YouTubeMusic.search(q).then((r) {
      if (!mounted || seq != _ytSeq) return;
      setState(() {
        _songs = r;
        _songsLoading = false;
      });
    }, onError: (Object e) {
      if (!mounted || seq != _ytSeq) return;
      final detail = e is PlatformException ? (e.message ?? e.code) : '$e';
      setState(() {
        _songs = const [];
        _songsLoading = false;
        _songsError = 'Couldn\'t reach YouTube Music.\n\nDetails: $detail';
      });
    });
    // Artists and albums are extras: if they fail, their rows just stay hidden.
    YouTubeMusic.searchArtists(q).then((r) {
      if (!mounted || seq != _ytSeq) return;
      setState(() {
        _artists = r;
        _artistsLoading = false;
      });
    }, onError: (Object _) {
      if (!mounted || seq != _ytSeq) return;
      setState(() {
        _artists = const [];
        _artistsLoading = false;
      });
    });
    YouTubeMusic.searchAlbums(q).then((r) {
      if (!mounted || seq != _ytSeq) return;
      setState(() {
        _albums = r;
        _albumsLoading = false;
      });
    }, onError: (Object _) {
      if (!mounted || seq != _ytSeq) return;
      setState(() {
        _albums = const [];
        _albumsLoading = false;
      });
    });
  }

  Widget _tabs(AppPalette pal) {
    Widget pill(int index, IconData icon, String label) {
      final selected = _tab == index;
      return Expanded(
        child: SquishyGesture(
          pressedScale: 0.96,
          onTap: () => _setTab(index),
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 220),
            curve: Curves.easeOutCubic,
            height: 42,
            decoration: BoxDecoration(
              color: selected ? pal.accent : pal.surface,
              borderRadius: BorderRadius.circular(21),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(icon,
                    size: 18,
                    color: selected ? pal.onAccent : Colors.white70),
                const SizedBox(width: 8),
                Text(
                  label,
                  style: TextStyle(
                    color: selected ? pal.onAccent : Colors.white70,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return Row(
      children: [
        pill(0, Icons.library_music_rounded, 'Library'),
        const SizedBox(width: 10),
        pill(1, Icons.play_circle_fill_rounded, 'YouTube Music'),
      ],
    );
  }

  Widget _note(String text) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 2),
      child: SelectableText(text, style: const TextStyle(color: Colors.white54)),
    );
  }

  Widget _spinner(AppPalette pal) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 18),
        child: Center(
          child: SizedBox(
            width: 26,
            height: 26,
            child: CircularProgressIndicator(strokeWidth: 2.5, color: pal.accent),
          ),
        ),
      );

  List<Widget> _libraryResults(AppPalette pal) {
    final tracks = audioHandler.tracks;
    final q = _query.toLowerCase();
    final filtered = tracks.where((t) {
      return t.title.toLowerCase().contains(q) ||
          t.artist.toLowerCase().contains(q) ||
          t.album.toLowerCase().contains(q);
    }).toList();
    if (filtered.isEmpty) {
      return [
        const Padding(
          padding: EdgeInsets.only(top: 40),
          child: Center(
            child: Text('No songs found.',
                style: TextStyle(color: Colors.white54)),
          ),
        ),
      ];
    }
    return [
      for (final t in filtered)
        TrackRow(
          track: t,
          palette: pal,
          active: audioHandler.currentTrack?.id == t.id,
          onTap: () {
            final idx = tracks.indexOf(t);
            Navigator.pop(context);
            playAndOpen(widget.parentContext, idx);
          },
          onMore: () => showAddToPlaylistSheet(context, t),
        ),
    ];
  }

  List<Widget> _ytResults(AppPalette pal) {
    if (_query.trim().length < 2) {
      final history = appState.b('search_history_on', true) ? _history : const <String>[];
      return [
        if (history.isNotEmpty) ...[
          Row(
            children: [
              Expanded(child: ytSectionHeader('Recent searches')),
              TextButton(
                onPressed: () {
                  YouTubeMusic.prefs?.remove('search_history');
                  setState(() {});
                },
                child: const Text('Clear'),
              ),
            ],
          ),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              for (final h in history)
                ActionChip(
                  avatar: const Icon(Icons.history_rounded, size: 18),
                  label: Text(h),
                  onPressed: () => _useHistory(h),
                ),
            ],
          ),
        ] else
          const Padding(
            padding: EdgeInsets.only(top: 40),
            child: Center(
              child: Text(
                'Search YouTube Music for songs, artists and albums.',
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.white54),
              ),
            ),
          ),
      ];
    }
    final out = <Widget>[];

    if (_artists.isNotEmpty) {
      out.add(ytSectionHeader('Artists'));
      out.add(SizedBox(
        height: 132,
        child: ListView.separated(
          scrollDirection: Axis.horizontal,
          itemCount: _artists.length,
          separatorBuilder: (_, __) => const SizedBox(width: 14),
          itemBuilder: (_, i) => YtArtistTile(artist: _artists[i]),
        ),
      ));
    } else if (_artistsLoading) {
      out.add(const SizedBox(height: 4));
    }

    out.add(ytSectionHeader('Songs'));
    if (_songsLoading && _songs.isEmpty) {
      out.add(_spinner(pal));
    } else if (_songsError != null) {
      out.add(_note(_songsError!));
    } else if (_songs.isEmpty) {
      out.add(_note('No songs found on YouTube Music.'));
    } else {
      for (final t in _songs) {
        out.add(YtTrackRow(track: t, onPlay: () {
          Navigator.pop(context);
          audioHandler.playYouTubeTrack(t);
          openPlayer(widget.parentContext);
        }));
      }
    }

    if (_albums.isNotEmpty) {
      out.add(ytSectionHeader('Albums'));
      out.add(SizedBox(
        height: 196,
        child: ListView.separated(
          scrollDirection: Axis.horizontal,
          itemCount: _albums.length,
          separatorBuilder: (_, __) => const SizedBox(width: 14),
          itemBuilder: (_, i) => YtAlbumTile(album: _albums[i]),
        ),
      ));
    }
    out.add(const SizedBox(height: 24));
    return out;
  }

  @override
  Widget build(BuildContext context) {
    final pal = appState.palette;
    final ytAvailable = Platform.isAndroid;
    final children = (_tab == 1 && ytAvailable)
        ? _ytResults(pal)
        : _libraryResults(pal);

    return Padding(
      padding: EdgeInsets.only(bottom: MediaQuery.of(context).viewInsets.bottom),
      child: SizedBox(
        height: MediaQuery.of(context).size.height * 0.8,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 0),
          child: Column(
            children: [
              TextField(
                controller: _ctrl,
                autofocus: true,
                style: const TextStyle(color: Colors.white),
                decoration: InputDecoration(
                  hintText: _tab == 1
                      ? 'Search YouTube Music...'
                      : 'Search your library...',
                  hintStyle: const TextStyle(color: Colors.white54),
                  prefixIcon: Icon(Icons.search, color: pal.accent),
                  filled: true,
                  fillColor: pal.surface,
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(28),
                    borderSide: BorderSide.none,
                  ),
                ),
                textInputAction: TextInputAction.search,
                onChanged: _onQueryChanged,
                onSubmitted: (v) {
                  final q = v.trim();
                  if (_tab == 1 && q.length >= 2) {
                    _debounce?.cancel();
                    _searchYt(q);
                  }
                },
              ),
              if (ytAvailable) ...[
                const SizedBox(height: 12),
                _tabs(pal),
              ],
              const SizedBox(height: 8),
              Expanded(
                child: ListView(
                  keyboardDismissBehavior:
                      ScrollViewKeyboardDismissBehavior.onDrag,
                  children: children,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// YouTube Music: shared widgets, artist page, album page
// ─────────────────────────────────────────────────────────────────────────────

/// Renders YouTube Music shelves (home feed): songs as swipeable columns,
/// videos as wide cards, albums/playlists as covers, artists as circles.
// ═══════════════════════ Apple Music style widgets ═══════════════════════

const Color kAmTint = Color(0xFF2F8CFF);
const Color kAmRed = Color(0xFFFA2D48);

const List<(String, Color, String)> kAmGenres = [
  ('Charts', Color(0xFF8A8A1F), 'Top charts'),
  ('Alternative', Color(0xFFC6C02A), 'Alternative'),
  ('Hip-Hop', Color(0xFF5C8EEB), 'Hip-Hop'),
  ('Rock', Color(0xFFE6613D), 'Rock'),
  ('Hits', Color(0xFFDDB400), 'Top hits'),
  ('Pop', Color(0xFFE2688B), 'Pop hits'),
  ('Country', Color(0xFFD28A3B), 'Country'),
  ('Dance', Color(0xFF3BBC7E), 'Dance'),
  ('R&B', Color(0xFF8B6FDF), 'R&B'),
  ('Throwbacks', Color(0xFF5276E6), 'Throwback hits'),
  ('Chill', Color(0xFF6E8D9C), 'Chill'),
  ('Workout', Color(0xFFD94848), 'Workout'),
  ('Indie', Color(0xFF4FA59A), 'Indie'),
  ('Latin', Color(0xFFE07E3C), 'Latin'),
];

class AmItem {
  final String title;
  final String subtitle;
  final Widget Function(double size) cover;
  final VoidCallback onTap;
  final bool circle;
  const AmItem(this.title, this.subtitle, this.cover, this.onTap,
      {this.circle = false});
}

class AmData {
  final bool yt;
  final List<TrackItem> songs;
  final List<TrackItem> liked;
  final List<TrackItem> recent;
  final List<AmItem> playlists;
  final List<AmItem> mixes;
  final List<Color> mixColors;
  final List<AmItem> added;
  final List<TrackItem> addedTracks;
  final List<(String, List<AmItem>)> shelves;
  final List<AmItem> artists;
  final Object? err;
  final bool loading;
  const AmData({
    required this.yt,
    required this.songs,
    required this.liked,
    required this.recent,
    required this.playlists,
    required this.mixes,
    required this.mixColors,
    required this.added,
    required this.addedTracks,
    required this.shelves,
    required this.artists,
    this.err,
    this.loading = false,
  });
}

Widget amTitle(String title, {List<Widget> actions = const []}) {
  return Padding(
    padding: const EdgeInsets.fromLTRB(22, 22, 18, 4),
    child: Row(
      children: [
        Expanded(
          child: Text(
            title,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: Color(0xFFE2E2E4),
              fontSize: 38,
              fontWeight: FontWeight.w800,
              letterSpacing: -0.8,
            ),
          ),
        ),
        for (final a in actions) ...[const SizedBox(width: 12), a],
      ],
    ),
  );
}

Widget amSection(String title, {VoidCallback? onTap}) {
  return Padding(
    padding: const EdgeInsets.fromLTRB(22, 32, 22, 14),
    child: GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: Row(
        children: [
          Flexible(
            child: Text(
              title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 25,
                fontWeight: FontWeight.w700,
                letterSpacing: -0.3,
              ),
            ),
          ),
          if (onTap != null)
            const Icon(Icons.chevron_right_rounded,
                color: Colors.white54, size: 32),
        ],
      ),
    ),
  );
}

Widget amRow(List<AmItem> items, double w) {
  return SizedBox(
    height: w + 64,
    child: ListView.separated(
      scrollDirection: Axis.horizontal,
      padding: const EdgeInsets.symmetric(horizontal: 22),
      itemCount: items.length,
      separatorBuilder: (_, __) => const SizedBox(width: 16),
      itemBuilder: (_, i) => AmSquareCard(item: items[i], width: w),
    ),
  );
}

Widget amListRow(IconData icon, String label, VoidCallback onTap) {
  return InkWell(
    onTap: onTap,
    child: Padding(
      padding: const EdgeInsets.only(left: 22),
      child: Row(
        children: [
          SizedBox(
            width: 40,
            child: Icon(icon, color: Colors.white, size: 30),
          ),
          const SizedBox(width: 18),
          Expanded(
            child: Container(
              height: 64,
              margin: const EdgeInsets.only(right: 22),
              alignment: Alignment.centerLeft,
              decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: Colors.white12)),
              ),
              child: Text(label,
                  style: const TextStyle(color: Colors.white, fontSize: 22)),
            ),
          ),
        ],
      ),
    ),
  );
}

Widget amPlainRow(BuildContext context, Widget cover, String title,
    VoidCallback onTap,
    {bool circle = false, bool tint = false}) {
  return InkWell(
    onTap: onTap,
    child: Padding(
      padding: const EdgeInsets.fromLTRB(22, 6, 22, 6),
      child: Row(
        children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(circle ? 30 : 8),
            child: SizedBox(width: 60, height: 60, child: cover),
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Container(
              height: 72,
              alignment: Alignment.centerLeft,
              decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: Colors.white12)),
              ),
              child: Text(
                title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  color: tint ? kAmTint : Colors.white,
                  fontSize: 18,
                ),
              ),
            ),
          ),
        ],
      ),
    ),
  );
}

Widget _amBigButton(IconData icon, String label, VoidCallback onTap) {
  return SquishyGesture(
    pressedScale: 0.96,
    onTap: onTap,
    child: Container(
      height: 52,
      decoration: BoxDecoration(
        color: const Color(0xFF1C1C1E),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(icon, color: kAmTint, size: 24),
          const SizedBox(width: 6),
          Text(label,
              style: const TextStyle(
                  color: kAmTint, fontSize: 17, fontWeight: FontWeight.w600)),
        ],
      ),
    ),
  );
}

List<Widget> amSongRows(BuildContext context, List<TrackItem> list,
    void Function(List<TrackItem>, int) play) {
  return [
    for (var i = 0; i < list.length; i++)
      Padding(
        padding: const EdgeInsets.symmetric(horizontal: 22),
        child: TrackRow(
          track: list[i],
          palette: appState.palette,
          active: audioHandler.currentTrack?.id == list[i].id,
          onTap: () => play(list, i),
          onMore: () => list[i].isYouTube
              ? showYtAddToPlaylist(context, list[i])
              : showAddToPlaylistSheet(context, list[i]),
        ),
      ),
  ];
}

List<Widget> amSongList(BuildContext context, List<TrackItem> list,
    void Function(List<TrackItem>, int) play) {
  if (list.isEmpty) {
    return const [
      Padding(
        padding: EdgeInsets.all(40),
        child: Center(
          child: Text('No songs yet.',
              style: TextStyle(color: Colors.white54, fontSize: 16)),
        ),
      ),
    ];
  }
  return [
    Padding(
      padding: const EdgeInsets.fromLTRB(22, 10, 22, 14),
      child: Row(
        children: [
          Expanded(
            child: _amBigButton(
                Icons.play_arrow_rounded, 'Play', () => play(list, 0)),
          ),
          const SizedBox(width: 14),
          Expanded(
            child: _amBigButton(Icons.shuffle_rounded, 'Shuffle', () {
              audioHandler.setShuffleMode(AudioServiceShuffleMode.all);
              play(list, Random().nextInt(list.length));
            }),
          ),
        ],
      ),
    ),
    ...amSongRows(context, list, play),
  ];
}

class AmCircleButton extends StatelessWidget {
  final IconData icon;
  final VoidCallback? onTap;
  const AmCircleButton({super.key, required this.icon, this.onTap});

  @override
  Widget build(BuildContext context) {
    final box = Container(
      width: 52,
      height: 52,
      decoration: BoxDecoration(
        color: const Color(0xFF1C1C1E),
        shape: BoxShape.circle,
        border: Border.all(color: Colors.white12),
