class AmNavBar extends StatelessWidget {
  final int selected;
  final ValueChanged<int> onSelect;
  const AmNavBar({super.key, required this.selected, required this.onSelect});

  static const _items = [
    (Icons.home_rounded, 'Home'),
    (Icons.grid_view_rounded, 'New'),
    (Icons.sensors_rounded, 'Radio'),
    (Icons.library_music_rounded, 'Library'),
    (Icons.search_rounded, 'Search'),
  ];

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 62,
      padding: const EdgeInsets.all(3),
      decoration: BoxDecoration(
        color: const Color(0xFF1E1E20).withOpacity(0.97),
        borderRadius: BorderRadius.circular(31),
        border: Border.all(color: Colors.white10),
        boxShadow: const [
          BoxShadow(color: Colors.black54, blurRadius: 24, offset: Offset(0, 8)),
        ],
      ),
      child: LayoutBuilder(
        builder: (context, k) {
          final w = k.maxWidth / _items.length;
          return Stack(
            children: [
              AnimatedPositioned(
                duration: const Duration(milliseconds: 320),
                curve: Curves.easeOutCubic,
                left: w * selected,
                top: 0,
                bottom: 0,
                width: w,
                child: Container(
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.09),
                    borderRadius: BorderRadius.circular(28),
                  ),
                ),
              ),
              Row(
                children: [
                  for (var i = 0; i < _items.length; i++)
                    SizedBox(
                      width: w,
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: () => onSelect(i),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(_items[i].$1,
                                size: 23,
                                color: i == selected ? kAmTint : Colors.white),
                            const SizedBox(height: 1),
                            Text(
                              _items[i].$2,
                              style: TextStyle(
                                fontSize: 10.5,
                                fontWeight: FontWeight.w600,
                                color: i == selected ? kAmTint : Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ],
          );
        },
      ),
    );
  }
}

