// ── Apple Music style player ───────────────────────────────────────────

class AmPlayerView extends StatelessWidget {
  final TrackItem track;
  final bool playing;
  final bool loading;
  final bool shuffle;
  final AudioServiceRepeatMode repeat;
  final bool liked;

  const AmPlayerView({
    super.key,
    required this.track,
    required this.playing,
    required this.loading,
    required this.shuffle,
    required this.repeat,
    required this.liked,
  });

  @override
  Widget build(BuildContext context) {
    Widget circle(IconData icon, bool filled, VoidCallback onTap) {
      return SquishyGesture(
        pressedScale: 0.88,
        onTap: onTap,
        child: Container(
          width: 38,
          height: 38,
          decoration: BoxDecoration(
            color: filled ? Colors.white : Colors.white.withOpacity(0.2),
            shape: BoxShape.circle,
          ),
          child: Icon(icon,
              size: 21, color: filled ? const Color(0xFF3A2A2E) : Colors.white),
        ),
      );
    }

    Widget bottomIcon(IconData icon, bool on, VoidCallback onTap) {
      return SquishyGesture(
        pressedScale: 0.85,
        onTap: onTap,
        child: Container(
          width: 48,
          height: 38,
          decoration: BoxDecoration(
            color: on ? Colors.white.withOpacity(0.2) : Colors.transparent,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Icon(icon,
              size: 23, color: on ? Colors.white : Colors.white.withOpacity(0.7)),
        ),
      );
    }

    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          AmArtBackground(track: track),
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 28),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const SizedBox(height: 8),
                  Center(
                    child: GestureDetector(
                      onTap: () => Navigator.of(context).pop(),
                      child: Container(
                        width: 40,
                        height: 5,
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.35),
                          borderRadius: BorderRadius.circular(3),
                        ),
                      ),
                    ),
                  ),
                  Expanded(
                    child: Center(
                      child: AspectRatio(
                        aspectRatio: 1,
                        child: AnimatedScale(
                          scale: playing ? 1.0 : 0.84,
                          duration: const Duration(milliseconds: 450),
                          curve: Curves.easeOutBack,
                          child: Container(
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(14),
                              boxShadow: [
                                BoxShadow(
                                  color: Colors.black
                                      .withOpacity(playing ? 0.45 : 0.25),
                                  blurRadius: 34,
                                  offset: const Offset(0, 16),
                                ),
                              ],
                            ),
                            child: Hero(
                              tag: 'now_playing_art',
                              createRectTween: _arcTween,
                              flightShuttleBuilder: _artShuttle,
                              child: SwipeArtCarousel(
                                track: track,
                                playing: playing,
                                radius: 14,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(height: 10),
                  Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              track.title,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 20,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              track.artist,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.62),
                                fontSize: 17,
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 12),
                      circle(liked ? Icons.star_rounded : Icons.star_border_rounded,
                          liked, () {
                        HapticFeedback.lightImpact();
                        appState.toggleLike(track.id);
                      }),
                      const SizedBox(width: 14),
                      circle(Icons.more_vert_rounded, false,
                          () => showAddToPlaylistSheet(context, track)),
                    ],
                  ),
                  const SizedBox(height: 26),
                  AmSeekBar(
                    fallbackSeconds: track.durationSeconds,
                    label: track.isYouTube ? 'YouTube Music' : 'On this phone',
                    labelIcon: track.isYouTube
                        ? Icons.play_circle_outline_rounded
                        : Icons.phone_android_rounded,
                  ),
                  const SizedBox(height: 22),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      SquishyGesture(
                        pressedScale: 0.8,
                        onTap: audioHandler.skipToPrevious,
                        child: const SizedBox(
                          width: 70,
                          height: 70,
                          child: Icon(Icons.fast_rewind_rounded,
                              color: Colors.white, size: 46),
                        ),
                      ),
                      SquishyGesture(
                        pressedScale: 0.9,
                        onTap: () =>
                            playing ? audioHandler.pause() : audioHandler.play(),
                        child: SizedBox(
                          width: 90,
                          height: 90,
                          child: loading
                              ? const Center(
                                  child: SizedBox(
                                    width: 38,
                                    height: 38,
                                    child: CircularProgressIndicator(
                                        strokeWidth: 3, color: Colors.white),
                                  ),
                                )
                              : AnimatedSwitcher(
                                  duration: const Duration(milliseconds: 180),
                                  transitionBuilder: (c, a) =>
                                      ScaleTransition(scale: a, child: c),
                                  child: Icon(
                                    playing
                                        ? Icons.pause_rounded
                                        : Icons.play_arrow_rounded,
                                    key: ValueKey(playing),
                                    color: Colors.white,
                                    size: 60,
                                  ),
                                ),
                        ),
                      ),
                      SquishyGesture(
                        pressedScale: 0.8,
                        onTap: audioHandler.skipToNext,
                        child: const SizedBox(
                          width: 70,
                          height: 70,
                          child: Icon(Icons.fast_forward_rounded,
                              color: Colors.white, size: 46),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 26),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      bottomIcon(Icons.shuffle_rounded, shuffle, () {
                        audioHandler.setShuffleMode(shuffle
                            ? AudioServiceShuffleMode.none
                            : AudioServiceShuffleMode.all);
                      }),
                      bottomIcon(
                          repeat == AudioServiceRepeatMode.one
                              ? Icons.repeat_one_rounded
                              : Icons.repeat_rounded,
                          repeat != AudioServiceRepeatMode.none, () {
                        final next = switch (repeat) {
                          AudioServiceRepeatMode.none => AudioServiceRepeatMode.all,
                          AudioServiceRepeatMode.all => AudioServiceRepeatMode.one,
                          _ => AudioServiceRepeatMode.none,
                        };
                        audioHandler.setRepeatMode(next);
                      }),
                      bottomIcon(Icons.tune_rounded,
                          soundModified,
                          () => showPlaybackSheet(context)),
                      bottomIcon(Icons.format_list_bulleted_rounded, false,
                          () => showQueueSheet(context)),
                    ],
                  ),
                  const SizedBox(height: 14),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

/// Blurred-looking album art behind the player. Instead of a live blur
/// (which re-blurs every frame while the player slides in/out and caused the
/// lag), the art is decoded at 24 px and stretched: it looks blurred and
/// costs almost nothing to draw.
class TinyArtBackdrop extends StatelessWidget {
  final TrackItem track;
  final double dim;
  const TinyArtBackdrop({super.key, required this.track, this.dim = 0.4});

  @override
  Widget build(BuildContext context) {
    final fallback = DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: track.artColors.length >= 2
              ? track.artColors.take(2).toList()
              : [track.artColors.first, Colors.black],
        ),
      ),
    );
    return IgnorePointer(
      child: RepaintBoundary(
        child: Stack(
          fit: StackFit.expand,
          children: [
            AnimatedSwitcher(
              duration: const Duration(milliseconds: 500),
              child: FutureBuilder<Uint8List?>(
                key: ValueKey(track.id),
                future: loadArt(track),
                builder: (context, snap) {
                  final bytes = snap.data;
                  if (bytes == null || bytes.isEmpty) return fallback;
                  return Image.memory(
                    bytes,
                    cacheWidth: 24,
                    fit: BoxFit.cover,
                    width: double.infinity,
                    height: double.infinity,
                    filterQuality: FilterQuality.medium,
                    gaplessPlayback: true,
                    errorBuilder: (_, __, ___) => fallback,
                  );
                },
              ),
            ),
            ColoredBox(color: Colors.black.withOpacity(dim)),
          ],
        ),
      ),
    );
  }
}

/// Apple Music style background: soft blobs of the album's colours drifting
/// slowly. Plain gradients (no blur pass), so it stays smooth.
class AmArtBackground extends StatefulWidget {
  final TrackItem track;
  const AmArtBackground({super.key, required this.track});

  @override
  State<AmArtBackground> createState() => _AmArtBackgroundState();
}

class _AmArtBackgroundState extends State<AmArtBackground>
    with SingleTickerProviderStateMixin {
  late final AnimationController _t = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 26),
  )..repeat();

  @override
  void dispose() {
    _t.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Color>(
      future: artSeedFor(widget.track),
      builder: (context, snap) {
        final seed = snap.data ?? widget.track.artColors.first;
        final hsl = HSLColor.fromColor(seed);
        Color shade(double dh, double l, [double s = 0.65]) => hsl
            .withHue((hsl.hue + dh) % 360)
            .withSaturation((hsl.saturation * s + 0.15).clamp(0.0, 1.0))
            .withLightness(l)
            .toColor();
        final base = shade(0, 0.16, 0.5);
        final c1 = shade(0, 0.42);
        final c2 = shade(28, 0.34);
        final c3 = shade(-30, 0.28);
        return IgnorePointer(
          child: RepaintBoundary(
            child: TweenAnimationBuilder<Color?>(
              tween: ColorTween(end: base),
              duration: const Duration(milliseconds: 900),
              builder: (context, b, _) => AnimatedBuilder(
                animation: _t,
                builder: (context, _) => CustomPaint(
                  painter: _AmBlobPainter(
                    _t.value,
                    b ?? base,
                    [c1, c2, c3],
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

class _AmBlobPainter extends CustomPainter {
  final double t;
  final Color base;
  final List<Color> colors;
  _AmBlobPainter(this.t, this.base, this.colors);

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Offset.zero & size, Paint()..color = base);
    final a = t * 2 * pi;
    final w = size.width, h = size.height;
    final spots = [
      Offset(w * (0.3 + 0.18 * sin(a)), h * (0.25 + 0.1 * cos(a * 1.3))),
      Offset(w * (0.75 + 0.15 * cos(a * 0.8)), h * (0.5 + 0.14 * sin(a * 1.1))),
      Offset(w * (0.35 + 0.2 * cos(a * 1.2)), h * (0.82 + 0.08 * sin(a * 0.9))),
    ];
    for (var i = 0; i < spots.length; i++) {
      final r = max(w, h) * (0.55 + 0.05 * sin(a + i));
      canvas.drawCircle(
        spots[i],
        r,
        Paint()
          ..shader = RadialGradient(
            colors: [colors[i].withOpacity(0.75), colors[i].withOpacity(0)],
          ).createShader(Rect.fromCircle(center: spots[i], radius: r)),
      );
    }
    // Slight darkening toward the bottom so the controls stay readable.
    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Colors.black.withOpacity(0.05), Colors.black.withOpacity(0.35)],
        ).createShader(Offset.zero & size),
    );
  }

  @override
  bool shouldRepaint(covariant _AmBlobPainter old) =>
      old.t != t || old.base != base || old.colors != colors;
}

/// Thick rounded seek bar with times underneath and a source label.
class AmSeekBar extends StatefulWidget {
  final int fallbackSeconds;
  final String label;
  final IconData labelIcon;
  const AmSeekBar({
    super.key,
    required this.fallbackSeconds,
    required this.label,
    required this.labelIcon,
  });

  @override
  State<AmSeekBar> createState() => _AmSeekBarState();
}

class _AmSeekBarState extends State<AmSeekBar> {
  double? _drag; // 0..1 while dragging

  String _fmt(Duration d) {
    final s = d.inSeconds.abs();
    return '${s ~/ 60}:${(s % 60).toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    return TrackProgress(
      fallbackSeconds: widget.fallbackSeconds,
      builder: (context, pos, dur) {
        final total = dur.inMilliseconds <= 0 ? 1 : dur.inMilliseconds;
        final value = _drag ?? (pos.inMilliseconds / total).clamp(0.0, 1.0);
        final shown = Duration(milliseconds: (value * total).round());
        final left = dur - shown;
        return LayoutBuilder(
          builder: (context, k) {
            void update(Offset local) => setState(() =>
                _drag = (local.dx / k.maxWidth).clamp(0.0, 1.0).toDouble());
            return Column(
              children: [
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onHorizontalDragStart: (d) => update(d.localPosition),
                  onHorizontalDragUpdate: (d) => update(d.localPosition),
                  onHorizontalDragEnd: (_) {
                    final v = _drag;
                    if (v != null) {
                      audioHandler
                          .seek(Duration(milliseconds: (v * total).round()));
                    }
                    setState(() => _drag = null);
                  },
                  onTapUp: (d) {
                    final v = (d.localPosition.dx / k.maxWidth).clamp(0.0, 1.0);
                    audioHandler
                        .seek(Duration(milliseconds: (v * total).round()));
                  },
                  child: SizedBox(
                    height: 30,
                    child: Center(
                      child: AnimatedContainer(
                        duration: const Duration(milliseconds: 160),
                        height: _drag != null ? 14 : 9,
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.22),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        alignment: Alignment.centerLeft,
                        child: FractionallySizedBox(
                          widthFactor: value.toDouble(),
                          heightFactor: 1,
                          child: Container(
                            decoration: BoxDecoration(
                              color: Colors.white
                                  .withOpacity(_drag != null ? 0.95 : 0.7),
                              borderRadius: BorderRadius.circular(8),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 4),
                Row(
                  children: [
                    SizedBox(
                      width: 70,
                      child: Text(_fmt(shown),
                          style: TextStyle(
                              color: Colors.white.withOpacity(0.5),
                              fontSize: 14,
                              fontFeatures: const [ui.FontFeature.tabularFigures()])),
                    ),
                    Expanded(
                      child: Center(
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 4),
                          decoration: BoxDecoration(
                            color: Colors.white.withOpacity(0.14),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(widget.labelIcon,
                                  size: 15,
                                  color: Colors.white.withOpacity(0.75)),
                              const SizedBox(width: 5),
                              Text(widget.label,
                                  style: TextStyle(
                                      color: Colors.white.withOpacity(0.75),
                                      fontSize: 13.5,
                                      fontWeight: FontWeight.w600)),
                            ],
                          ),
                        ),
                      ),
                    ),
                    SizedBox(
                      width: 70,
                      child: Text('-${_fmt(left)}',
                          textAlign: TextAlign.right,
                          style: TextStyle(
                              color: Colors.white.withOpacity(0.5),
                              fontSize: 14,
                              fontFeatures: const [ui.FontFeature.tabularFigures()])),
                    ),
                  ],
                ),
              ],
            );
          },
        );
      },
    );
  }
}

// ═══════════════════ Shared player helpers (lyrics, sleep, share) ═══════════

final Map<String, Future<Color>> _artSeedCache = {};

/// Main colour of a song's artwork (cached per song).
Future<Color> artSeedFor(TrackItem t) => _artSeedCache.putIfAbsent(t.id, () async {
      try {
        final bytes = await loadArt(t);
        if (bytes != null && bytes.isNotEmpty) {
          final c = await _dominantColor(bytes);
          if (c != null) return c;
        }
      } catch (_) {}
      return t.artColors.first;
    });

/// Copies a link to the song (or its name for local files).
Future<void> shareTrack(TrackItem t) async {
  final text = t.ytVideoId != null
      ? 'https://music.youtube.com/watch?v=${t.ytVideoId}'
      : '${t.title} — ${t.artist}';
  await Clipboard.setData(ClipboardData(text: text));
  HapticFeedback.lightImpact();
  appNotice.value =
      t.ytVideoId != null ? 'Song link copied.' : 'Song name copied.';
}

void showSleepTimerSheet(BuildContext context) {
  showModalBottomSheet(
    context: context,
    showDragHandle: true,
    builder: (ctx) {
      Widget opt(String label, VoidCallback onTap) => ListTile(
            title: Text(label),
            onTap: () {
              onTap();
              Navigator.pop(ctx);
            },
          );
      return SafeArea(
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ValueListenableBuilder<String?>(
                valueListenable: audioHandler.sleepLabel,
                builder: (_, label, __) => ListTile(
                  leading: const Icon(Icons.bedtime_rounded),
                  title: const Text('Sleep timer',
                      style:
                          TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
                  subtitle: Text(label ?? 'Off'),
                ),
              ),
              opt('Off', () => audioHandler.setSleepTimer(null)),
              for (final m in [5, 15, 30, 45, 60, 90])
                opt('$m minutes',
                    () => audioHandler.setSleepTimer(Duration(minutes: m))),
              opt('End of this song',
                  () => audioHandler.setSleepTimer(null, endOfSong: true)),
            ],
          ),
        ),
      );
    },
  );
}

// ── Lyrics (from LRCLIB, a free open lyrics database) ─────────────────────

class LyricsResult {
  final List<(Duration, String)> synced;
  final String? plain;
  final String source;
  const LyricsResult(this.synced, this.plain, [this.source = 'LRCLIB']);
  bool get isEmpty => synced.isEmpty && (plain == null || plain!.trim().isEmpty);
}

final Map<String, Future<LyricsResult?>> _lyricsCache = {};

Future<LyricsResult?> fetchLyrics(TrackItem t) =>
    _lyricsCache.putIfAbsent(t.id, () => _fetchLyrics(t));

String _lyricsClean(String s) => s
    .replaceAll(
        RegExp(r'\s*[\(\[](feat|ft|with|prod|official|lyric|audio|video)[^\)\]]*[\)\]]',
            caseSensitive: false),
        '')
    .trim();

/// Tries several lyric sources, best first:
///  1. LRCLIB, matched by title + artist (synced, time-stamped lines)
///  2. LRCLIB free-text search (catches odd titles/artist spellings)
///  3. YouTube Music's own lyrics (huge catalogue; plain text). Local songs
///     are matched to YouTube Music by searching "title artist".
Future<LyricsResult?> _fetchLyrics(TrackItem t) async {
  final errors = <String>[];
  final title = _lyricsClean(t.title);
  final artist = t.artist
      .split(RegExp(r',|&| x | feat\.? | ft\.? ', caseSensitive: false))
      .first
      .trim();
  final hasArtist = artist.isNotEmpty && artist != 'Unknown Artist';

  // 1 + 2: LRCLIB.
  LyricsResult? plainFallback;
  for (final params in [
    {'track_name': title, if (hasArtist) 'artist_name': artist},
    {'q': hasArtist ? '$title $artist' : title},
  ]) {
    try {
      final r = await _lrclibSearch(t, params);
      if (r != null && r.synced.isNotEmpty) return r;
      plainFallback ??= r;
    } catch (e) {
      errors.add('LRCLIB: $e');
    }
  }

  // 3: YouTube Music.
  try {
    var videoId = t.ytVideoId;
    if (videoId == null && Platform.isAndroid) {
      final hits =
          await YouTubeMusic.search(hasArtist ? '$title $artist' : title);
      if (hits.isNotEmpty) videoId = hits.first.ytVideoId;
    }
    if (videoId != null) {
      final raw =
          await _ytChannel.invokeMethod('ytLyrics', {'videoId': videoId});
      if (raw is Map) {
        final plain = (raw['plain'] ?? '').toString();
        if (plain.trim().isNotEmpty) {
          // Prefer YouTube Music's text over a plain LRCLIB copy only when
          // LRCLIB had nothing at all.
          final src = (raw['source'] ?? '').toString().trim();
          return plainFallback ??
              LyricsResult(const [], plain,
                  src.isEmpty ? 'YouTube Music' : 'YouTube Music · $src');
        }
      }
    }
  } catch (e) {
    errors.add('YouTube Music: ${e is PlatformException ? (e.message ?? e.code) : e}');
  }

  if (plainFallback != null) return plainFallback;
  if (errors.isNotEmpty) throw Exception(errors.join('\n'));
  return null;
}

Future<LyricsResult?> _lrclibSearch(
    TrackItem t, Map<String, String> params) async {
  final client = HttpClient()..connectionTimeout = const Duration(seconds: 10);
  try {
    final req =
        await client.getUrl(Uri.https('lrclib.net', '/api/search', params));
    req.headers.set('User-Agent', 'AlexLMP/$kAppVersion (github.com/$kGithubRepo)');
    final res = await req.close();
    if (res.statusCode != 200) {
      throw Exception('lrclib.net answered ${res.statusCode}');
    }
    final body = await utf8.decoder.bind(res).join();
    final list = jsonDecode(body);
    if (list is! List || list.isEmpty) return null;
    String norm(String s) =>
        s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9$]'), '');
    final wantTitle = norm(_lyricsClean(t.title));
    Map<String, dynamic>? best;
    double bestScore = double.infinity;
    for (final e in list) {
      if (e is! Map) continue;
      final m = Map<String, dynamic>.from(e);
      if (m['instrumental'] == true) continue;
      final dur = (m['duration'] as num?)?.toDouble() ?? 0;
      var score = t.durationSeconds > 0 && dur > 0
          ? (dur - t.durationSeconds).abs()
          : 5.0;
      final gotTitle = norm((m['trackName'] ?? '').toString());
      if (gotTitle != wantTitle &&
          !gotTitle.contains(wantTitle) &&
          !wantTitle.contains(gotTitle)) {
        score += 60; // probably a different song
      }
      if ((m['syncedLyrics'] ?? '').toString().isEmpty) score += 20;
      if (score < bestScore) {
        bestScore = score;
        best = m;
      }
    }
    if (best == null || bestScore >= 60) return null;
    final synced = <(Duration, String)>[];
    final raw = (best['syncedLyrics'] ?? '').toString();
    final re = RegExp(r'^\[(\d+):(\d+(?:\.\d+)?)\](.*)$');
    for (final line in const LineSplitter().convert(raw)) {
      final m = re.firstMatch(line.trim());
      if (m == null) continue;
      final mins = int.parse(m.group(1)!);
      final sec = double.parse(m.group(2)!);
      synced.add((
        Duration(milliseconds: ((mins * 60 + sec) * 1000).round()),
        m.group(3)!.trim(),
      ));
    }
    final plain = (best['plainLyrics'] ?? '').toString();
    final r = LyricsResult(synced, plain.isEmpty ? null : plain, 'LRCLIB');
    return r.isEmpty ? null : r;
  } finally {
    client.close();
  }
}

void showLyricsSheet(BuildContext context, TrackItem t) {
  Navigator.of(context).push(MaterialPageRoute(
    fullscreenDialog: true,
    builder: (_) => LyricsScreen(track: t),
  ));
}

class LyricsScreen extends StatefulWidget {
  final TrackItem track;
  const LyricsScreen({super.key, required this.track});

  @override
  State<LyricsScreen> createState() => _LyricsScreenState();
}

class _LyricsScreenState extends State<LyricsScreen> {
  final Map<int, GlobalKey> _keys = {};
  int _shown = -1;

  GlobalKey _key(int i) => _keys.putIfAbsent(i, () => GlobalKey());

  void _follow(int i) {
    if (i == _shown || i < 0) return;
    _shown = i;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final ctx = _keys[i]?.currentContext;
      if (ctx != null) {
        Scrollable.ensureVisible(ctx,
            alignment: 0.35,
            duration: const Duration(milliseconds: 420),
            curve: Curves.easeOutCubic);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: audioHandler.currentIndex,
      builder: (context, _) {
        final t = audioHandler.currentTrack ?? widget.track;
        return FutureBuilder<Color>(
          future: artSeedFor(t),
          builder: (context, seedSnap) {
            final cs = AppPalette.scheme(seedSnap.data ?? t.artColors.first);
            return Scaffold(
              backgroundColor: Color.lerp(cs.surface, cs.primary, 0.12),
              appBar: AppBar(
                backgroundColor: Colors.transparent,
                foregroundColor: cs.onSurface,
                actions: [
                  // Turns the lyrics shown over the player artwork on/off.
                  ListenableBuilder(
                    listenable: appState,
                    builder: (context, _) {
                      final on = appState.b('player_lyrics');
                      return Padding(
                        padding: const EdgeInsets.only(right: 12),
                        child: SquishyGesture(
                          pressedScale: 0.9,
                          onTap: () {
                            HapticFeedback.selectionClick();
                            appState.setB('player_lyrics', !on);
                          },
                          child: AnimatedContainer(
                            duration: const Duration(milliseconds: 250),
                            padding: const EdgeInsets.symmetric(
                                horizontal: 12, vertical: 8),
                            decoration: BoxDecoration(
                              color: on
                                  ? cs.primary
                                  : cs.onSurface.withOpacity(0.08),
                              borderRadius: BorderRadius.circular(20),
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(
                                  on
                                      ? Icons.subtitles_rounded
                                      : Icons.subtitles_off_outlined,
                                  size: 18,
                                  color: on ? cs.onPrimary : cs.onSurface,
                                ),
                                const SizedBox(width: 6),
                                Text(
                                  'On artwork',
                                  style: TextStyle(
                                    color: on ? cs.onPrimary : cs.onSurface,
                                    fontSize: 13,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
                ],
                title: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(t.title,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            fontSize: 18, fontWeight: FontWeight.w700)),
                    Text(t.artist,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                            fontSize: 14, color: cs.onSurfaceVariant)),
                  ],
                ),
              ),
              body: FutureBuilder<LyricsResult?>(
                key: ValueKey(t.id),
                future: fetchLyrics(t),
                builder: (context, snap) {
                  if (snap.connectionState != ConnectionState.done) {
                    return Center(
                        child: CircularProgressIndicator(color: cs.primary));
                  }
                  if (snap.hasError) {
                    return Center(
                      child: Padding(
                        padding: const EdgeInsets.all(28),
                        child: SelectableText(
                          'Couldn\'t load lyrics.\n\nDetails: ${snap.error}',
                          style: TextStyle(color: cs.onSurfaceVariant),
                        ),
                      ),
                    );
                  }
                  final r = snap.data;
                  if (r == null) {
                    return Center(
                      child: Text('No lyrics found for this song.',
                          style: TextStyle(
                              color: cs.onSurfaceVariant, fontSize: 16)),
                    );
                  }
                  if (r.synced.isEmpty) {
                    return SingleChildScrollView(
                      padding: const EdgeInsets.fromLTRB(26, 10, 26, 60),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(r.plain ?? '',
                              style: TextStyle(
                                  color: cs.onSurface,
                                  fontSize: 22,
                                  height: 1.5,
                                  fontWeight: FontWeight.w600)),
                          const SizedBox(height: 24),
                          Text('Lyrics from ${r.source}',
                              style: TextStyle(
                                  color: cs.onSurfaceVariant, fontSize: 12)),
                        ],
                      ),
                    );
                  }
                  return StreamBuilder<Duration>(
                    stream: audioHandler.player.positionStream,
                    builder: (context, posSnap) {
                      final pos = posSnap.data ?? audioHandler.player.position;
                      var idx = -1;
                      for (var i = 0; i < r.synced.length; i++) {
                        if (r.synced[i].$1 <= pos) idx = i;
                      }
                      _follow(idx);
                      return ListView(
                        padding: const EdgeInsets.fromLTRB(26, 20, 26, 300),
                        children: [
                          for (var i = 0; i < r.synced.length; i++)
                            GestureDetector(
                              key: _key(i),
                              behavior: HitTestBehavior.opaque,
                              onTap: () => audioHandler.seek(r.synced[i].$1),
                              child: Padding(
                                padding: const EdgeInsets.symmetric(vertical: 9),
                                child: AnimatedDefaultTextStyle(
                                  duration: const Duration(milliseconds: 250),
                                  style: TextStyle(
                                    color: i == idx
                                        ? cs.onSurface
                                        : cs.onSurface.withOpacity(
                                            i < idx ? 0.35 : 0.5),
                                    fontSize: i == idx ? 28 : 25,
                                    height: 1.3,
                                    fontWeight: FontWeight.w800,
                                  ),
                                  child: i == idx &&
                                          appState.b('word_lyrics', true) &&
                                          r.synced[i].$2.trim().isNotEmpty
                                      ? KaraokeLine(
                                          line: r.synced[i].$2,
                                          start: r.synced[i].$1,
                                          nextStart: i + 1 < r.synced.length
                                              ? r.synced[i + 1].$1
                                              : r.synced[i].$1 +
                                                  const Duration(seconds: 6),
                                          color: cs.onSurface,
                                        )
                                      : Text(r.synced[i].$2.isEmpty
                                          ? '♪'
                                          : r.synced[i].$2
                                              .replaceAll(RegExp(r'<\d+:\d+(?:\.\d+)?>'), '')),
                                ),
                              ),
                            ),
                          Padding(
                            padding: const EdgeInsets.only(top: 30),
                            child: Text('Lyrics from ${r.source}',
                                style: TextStyle(
                                    color: cs.onSurfaceVariant, fontSize: 12)),
                          ),
                        ],
                      );
                    },
                  );
                },
              ),
            );
          },
        );
      },
    );
  }
}

// ── Seek bar core (drag + tap to seek) ────────────────────────────────────

class PlayerSeek extends StatefulWidget {
  final int fallbackSeconds;
  final Widget Function(double value, bool dragging) track;
  final TextStyle timeStyle;
  final double height;
  const PlayerSeek({
    super.key,
    required this.fallbackSeconds,
    required this.track,
    required this.timeStyle,
    this.height = 36,
    this.showTimes = true,
  });

  final bool showTimes;

  @override
  State<PlayerSeek> createState() => _PlayerSeekState();
}

class _PlayerSeekState extends State<PlayerSeek> {
  double? _drag;

  String _fmt(Duration d) {
    final s = d.inSeconds.abs();
    final h = s ~/ 3600;
    final m = (s % 3600) ~/ 60;
    final sec = (s % 60).toString().padLeft(2, '0');
    return h > 0 ? '$h:${m.toString().padLeft(2, '0')}:$sec' : '$m:$sec';
  }

  @override
  Widget build(BuildContext context) {
    return TrackProgress(
      fallbackSeconds: widget.fallbackSeconds,
      builder: (context, pos, dur) {
        final total = dur.inMilliseconds <= 0 ? 1 : dur.inMilliseconds;
        final double value =
            _drag ?? (pos.inMilliseconds / total).clamp(0.0, 1.0).toDouble();
        final shown = Duration(milliseconds: (value * total).round());
        return LayoutBuilder(builder: (context, k) {
          double at(Offset p) => (p.dx / k.maxWidth).clamp(0.0, 1.0).toDouble();
          final bar = GestureDetector(
            behavior: HitTestBehavior.opaque,
            onHorizontalDragStart: (d) =>
                setState(() => _drag = at(d.localPosition)),
            onHorizontalDragUpdate: (d) =>
                setState(() => _drag = at(d.localPosition)),
            onHorizontalDragEnd: (_) {
              final v = _drag;
              if (v != null) {
                audioHandler.seek(Duration(milliseconds: (v * total).round()));
              }
              setState(() => _drag = null);
            },
            onTapUp: (d) => audioHandler.seek(
                Duration(milliseconds: (at(d.localPosition) * total).round())),
            child: SizedBox(
              height: widget.height,
              width: double.infinity,
              child: widget.track(value, _drag != null),
            ),
          );
          if (!widget.showTimes) return bar;
          return Column(
            children: [
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onHorizontalDragStart: (d) =>
                    setState(() => _drag = at(d.localPosition)),
                onHorizontalDragUpdate: (d) =>
                    setState(() => _drag = at(d.localPosition)),
                onHorizontalDragEnd: (_) {
                  final v = _drag;
                  if (v != null) {
                    audioHandler.seek(Duration(milliseconds: (v * total).round()));
                  }
                  setState(() => _drag = null);
                },
                onTapUp: (d) => audioHandler.seek(
                    Duration(milliseconds: (at(d.localPosition) * total).round())),
                child: SizedBox(
                  height: widget.height,
                  width: double.infinity,
                  child: widget.track(value, _drag != null),
                ),
              ),
              const SizedBox(height: 6),
              Row(
                children: [
                  Text(_fmt(shown), style: widget.timeStyle),
                  const Spacer(),
                  Text(_fmt(dur), style: widget.timeStyle),
                ],
              ),
            ],
          );
        });
      },
    );
  }
}

// ═══════════════════════ AlexLMP player (default) ═══════════════════════
// AlexLMP's own layout: "Playing from" header, artwork with a colour glow,
// an inline seek bar with the times on each side, a play button wrapped in
// a progress ring, and a dock of labelled shortcuts at the bottom.

class _RingPainter extends CustomPainter {
  final double value;
  final Color track;
  final Color fill;
  _RingPainter(this.value, this.track, this.fill);

  @override
  void paint(Canvas canvas, Size size) {
    final r = (size.shortestSide - 6) / 2;
    final c = size.center(Offset.zero);
    final base = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 4
      ..color = track;
    canvas.drawCircle(c, r, base);
    if (value > 0) {
      canvas.drawArc(
        Rect.fromCircle(center: c, radius: r),
        -pi / 2,
        2 * pi * value.clamp(0.0, 1.0),
        false,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 4
          ..strokeCap = StrokeCap.round
          ..color = fill,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _RingPainter old) =>
      old.value != value || old.fill != fill || old.track != track;
}

class AlexPlayerView extends StatelessWidget {
  final TrackItem track;
  final bool playing;
  final bool loading;
  final bool shuffle;
  final AudioServiceRepeatMode repeat;
  final bool liked;
  const AlexPlayerView({
    super.key,
    required this.track,
    required this.playing,
    required this.loading,
    required this.shuffle,
    required this.repeat,
    required this.liked,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Color>(
      future: artSeedFor(track),
      builder: (context, snap) {
        final seed = snap.data ?? track.artColors.first;
        final cs = AppPalette.scheme(seed);
        return AnimatedTheme(
          data: ThemeData(useMaterial3: true, colorScheme: cs),
          duration: const Duration(milliseconds: 500),
          child: _body(context, cs, seed),
        );
      },
    );
  }

  Widget _body(BuildContext context, ColorScheme cs, Color seed) {
    final glass = appState.liquidGlass;
    final immersive = appState.b('immersive_art');
    final accent = Color.lerp(cs.primary, Colors.white, 0.35)!;

    Widget pane(Widget child, {double r = 22, EdgeInsets? padding}) => glass
        ? LiquidGlassBox(
            borderRadius: BorderRadius.circular(r),
            fallbackColor: cs.surfaceContainerHigh,
            padding: padding,
            child: child,
          )
        : Container(
            padding: padding,
            decoration: BoxDecoration(
              color: cs.surfaceContainerHigh.withOpacity(0.85),
              borderRadius: BorderRadius.circular(r),
            ),
            child: child,
          );

    Widget iconBtn(IconData icon, VoidCallback onTap,
            {bool on = false, double size = 26}) =>
        SquishyGesture(
          pressedScale: 0.85,
          onTap: onTap,
          child: SizedBox(
            width: 48,
            height: 48,
            child: Icon(icon,
                size: size,
                color: on ? accent : cs.onSurface.withOpacity(0.75)),
          ),
        );

    Widget dockItem(IconData icon, String label, VoidCallback onTap,
            {bool on = false}) =>
        Expanded(
          child: SquishyGesture(
            pressedScale: 0.9,
            onTap: onTap,
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(icon, size: 22, color: on ? accent : cs.onSurface),
                  const SizedBox(height: 3),
                  Text(label,
                      style: TextStyle(
                          color: on ? accent : cs.onSurfaceVariant,
                          fontSize: 11.5,
                          fontWeight: FontWeight.w600)),
                ],
              ),
            ),
          ),
        );

    final source = liked
        ? 'Your likes'
        : track.isYouTube
            ? 'Streaming'
            : 'On this phone';

    final content = SafeArea(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 20),
        child: Column(
          children: [
            const SizedBox(height: 6),
            // ── Header
            Row(
              children: [
                iconBtn(Icons.expand_more_rounded,
                    () => Navigator.of(context).pop(),
                    size: 30),
                Expanded(
                  child: Column(
                    children: [
                      Text('PLAYING FROM',
                          style: TextStyle(
                              color: cs.onSurfaceVariant,
                              fontSize: 10.5,
                              letterSpacing: 1.6,
                              fontWeight: FontWeight.w700)),
                      const SizedBox(height: 2),
                      Text(source,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: cs.onSurface,
                              fontSize: 14.5,
                              fontWeight: FontWeight.w700)),
                    ],
                  ),
                ),
                iconBtn(Icons.more_vert_rounded,
                    () => showAddToPlaylistSheet(context, track)),
              ],
            ),
            // ── Artwork with a colour glow
            if (immersive) const Spacer() else Expanded(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(8, 18, 8, 18),
                child: Center(
                  child: AspectRatio(
                    aspectRatio: 1,
                    child: AnimatedScale(
                      scale: playing ? 1.0 : 0.92,
                      duration: const Duration(milliseconds: 400),
                      curve: Curves.easeOutBack,
                      child: Container(
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(30),
                          boxShadow: [
                            BoxShadow(
                              color: seed.withOpacity(playing ? 0.45 : 0.2),
                              blurRadius: 40,
                              spreadRadius: -6,
                              offset: const Offset(0, 14),
                            ),
                          ],
                        ),
                        child: Hero(
                          tag: 'now_playing_art',
                          createRectTween: _arcTween,
                          flightShuttleBuilder: _artShuttle,
                          child: SwipeArtCarousel(
                              track: track, playing: playing, radius: 30),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
            // ── Title + like
            Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(track.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: cs.onSurface,
                              fontSize: 22,
                              fontWeight: FontWeight.w800,
                              letterSpacing: -0.3)),
                      const SizedBox(height: 2),
                      GestureDetector(
                        onTap: () => goToArtist(context, track),
                        child: Text(track.artist,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color: accent,
                                fontSize: 16,
                                fontWeight: FontWeight.w600)),
                      ),
                    ],
                  ),
                ),
                SquishyGesture(
                  pressedScale: 0.8,
                  onTap: () {
                    HapticFeedback.lightImpact();
                    appState.toggleLike(track.id);
                  },
                  child: Padding(
                    padding: const EdgeInsets.all(6),
                    child: AnimatedSwitcher(
                      duration: const Duration(milliseconds: 420),
                      switchInCurve: Curves.elasticOut,
                      transitionBuilder: (c, a) =>
                          ScaleTransition(scale: a, child: c),
                      child: Icon(
                        liked
                            ? Icons.favorite_rounded
                            : Icons.favorite_border_rounded,
                        key: ValueKey(liked),
                        color: liked ? accent : cs.onSurfaceVariant,
                        size: 30,
                      ),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),
            // ── Inline seek bar: time | bar | time
            TrackProgress(
              fallbackSeconds: track.durationSeconds,
              builder: (context, pos, dur) {
                String f(Duration d) {
                  final s = d.inSeconds;
                  return '${s ~/ 60}:${(s % 60).toString().padLeft(2, '0')}';
                }

                final style = TextStyle(
                    color: cs.onSurfaceVariant,
                    fontSize: 12.5,
                    fontFeatures: const [ui.FontFeature.tabularFigures()]);
                return Row(
                  children: [
                    SizedBox(width: 40, child: Text(f(pos), style: style)),
                    Expanded(
                      child: PlayerSeek(
                        fallbackSeconds: track.durationSeconds,
                        height: 28,
                        showTimes: false,
                        timeStyle: const TextStyle(),
                        track: (v, dragging) => LayoutBuilder(builder: (_, k) {
                          final h = dragging ? 10.0 : 6.0;
                          return Align(
                            alignment: Alignment.centerLeft,
                            child: Container(
                              height: h,
                              width: k.maxWidth,
                              decoration: BoxDecoration(
                                color: cs.onSurface.withOpacity(0.15),
                                borderRadius: BorderRadius.circular(h),
                              ),
                              alignment: Alignment.centerLeft,
                              child: FractionallySizedBox(
                                widthFactor: v,
                                heightFactor: 1,
                                child: Container(
                                  decoration: BoxDecoration(
                                    gradient: LinearGradient(
                                        colors: [cs.primary, accent]),
                                    borderRadius: BorderRadius.circular(h),
                                  ),
                                ),
                              ),
                            ),
                          );
                        }),
                      ),
                    ),
                    SizedBox(
                      width: 40,
                      child: Text(f(dur),
                          textAlign: TextAlign.right, style: style),
                    ),
                  ],
                );
              },
            ),
            const SizedBox(height: 10),
            // ── Transport: play inside a progress ring
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                iconBtn(Icons.shuffle_rounded, () {
                  audioHandler.setShuffleMode(shuffle
                      ? AudioServiceShuffleMode.none
                      : AudioServiceShuffleMode.all);
                }, on: shuffle, size: 24),
                iconBtn(Icons.skip_previous_rounded, audioHandler.skipToPrevious,
                    size: 40),
                TrackProgress(
                  fallbackSeconds: track.durationSeconds,
                  builder: (context, pos, dur) {
                    final v = dur.inMilliseconds <= 0
                        ? 0.0
                        : pos.inMilliseconds / dur.inMilliseconds;
                    return SquishyGesture(
                      pressedScale: 0.9,
                      onTap: () =>
                          playing ? audioHandler.pause() : audioHandler.play(),
                      child: SizedBox(
                        width: 86,
                        height: 86,
                        child: CustomPaint(
                          painter: _RingPainter(
                              v, cs.onSurface.withOpacity(0.12), accent),
                          child: Center(
                            child: Container(
                              width: 68,
                              height: 68,
                              decoration: BoxDecoration(
                                color: accent,
                                shape: BoxShape.circle,
                              ),
                              child: loading
                                  ? Padding(
                                      padding: const EdgeInsets.all(20),
                                      child: CircularProgressIndicator(
                                          strokeWidth: 3,
                                          color: cs.onPrimaryContainer),
                                    )
                                  : Icon(
                                      playing
                                          ? Icons.pause_rounded
                                          : Icons.play_arrow_rounded,
                                      color: Colors.black87,
                                      size: 38),
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                ),
                iconBtn(Icons.skip_next_rounded, audioHandler.skipToNext,
                    size: 40),
                iconBtn(
                    repeat == AudioServiceRepeatMode.one
                        ? Icons.repeat_one_rounded
                        : Icons.repeat_rounded,
                    () => audioHandler.setRepeatMode(_nextRepeat(repeat)),
                    on: repeat != AudioServiceRepeatMode.none,
                    size: 24),
              ],
            ),
            const SizedBox(height: 14),
            // ── Dock
            pane(
              Row(
                children: [
                  dockItem(Icons.queue_music_rounded, 'Up next',
                      () => showQueueSheet(context)),
                  dockItem(Icons.lyrics_outlined, 'Lyrics',
                      () => showLyricsSheet(context, track)),
                  dockItem(Icons.graphic_eq_rounded, 'Sound',
                      () => showPlaybackSheet(context),
                      on: soundModified),
                  ValueListenableBuilder<String?>(
                    valueListenable: audioHandler.sleepLabel,
                    builder: (_, label, __) => dockItem(
                        Icons.bedtime_outlined,
                        'Sleep',
                        () => showSleepTimerSheet(context),
                        on: label != null),
                  ),
                  dockItem(Icons.ios_share_rounded, 'Share',
                      () => shareTrack(track)),
                ],
              ),
              r: 24,
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
            ),
            const SizedBox(height: 10),
          ],
        ),
      ),
    );

    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          // Same colour gradient with or without Liquid Glass (glass only
          // changes the dock).
          DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    Color.lerp(cs.surface, seed, 0.28)!,
                    Color.lerp(cs.surface, Colors.black, 0.35)!,
                    Colors.black,
                  ],
                  stops: const [0.0, 0.55, 1.0],
                ),
              ),
            ),
          if (immersive)
            Positioned(
              top: 0,
              left: 0,
              right: 0,
              child: ImmersiveArt(track: track, playing: playing),
            ),
          content,
        ],
      ),
    );
  }
}

