                ],
              ),
              const SizedBox(height: 10),
              PlayerSeek(
                fallbackSeconds: track.durationSeconds,
                timeStyle: TextStyle(
                    color: Colors.white.withOpacity(0.72),
                    fontSize: 13.5,
                    fontWeight: FontWeight.w500),
                track: (v, dragging) => LayoutBuilder(builder: (_, k) {
                  final w = k.maxWidth;
                  final thumb = dragging ? 22.0 : 18.0;
                  final x = v * (w - thumb);
                  return Stack(
                    alignment: Alignment.centerLeft,
                    children: [
                      Container(
                        height: 4,
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.2),
                          borderRadius: BorderRadius.circular(2),
                        ),
                      ),
                      Container(
                        width: x + thumb / 2,
                        height: 4,
                        decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(2),
                        ),
                      ),
                      Positioned(
                        right: 2,
                        child: Container(
                          width: 6,
                          height: 6,
                          decoration: const BoxDecoration(
                              color: Colors.white, shape: BoxShape.circle),
                        ),
                      ),
                      Positioned(
                        left: x,
                        child: Container(
                          width: thumb,
                          height: thumb,
                          decoration: const BoxDecoration(
                              color: Colors.white, shape: BoxShape.circle),
                        ),
                      ),
                    ],
                  );
                }),
              ),
              const SizedBox(height: 16),
              // Prev / next as plain circles; a wide play capsule between.
              Row(
                children: [
                  SquishyGesture(
                    pressedScale: 0.88,
                    onTap: audioHandler.skipToPrevious,
                    child: Container(
                      width: 66,
                      height: 66,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(color: Colors.white24, width: 1.5),
                      ),
                      child: const Icon(Icons.skip_previous_rounded,
                          color: Colors.white, size: 32),
                    ),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: pill(
                      loading
                          ? const SizedBox(
                              width: 30,
                              height: 30,
                              child: CircularProgressIndicator(
                                  strokeWidth: 3, color: Colors.black))
                          : Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Icon(
                                    playing
                                        ? Icons.pause_rounded
                                        : Icons.play_arrow_rounded,
                                    color: Colors.black,
                                    size: 34),
                                const SizedBox(width: 6),
                                Text(playing ? 'Pause' : 'Play',
                                    style: const TextStyle(
                                        color: Colors.black,
                                        fontSize: 17,
                                        fontWeight: FontWeight.w700)),
                              ],
                            ),
                      const Color(0xFFF2F1F3),
                      () => playing ? audioHandler.pause() : audioHandler.play(),
                      radius: 18,
                      height: 66,
                    ),
                  ),
                  const SizedBox(width: 14),
                  SquishyGesture(
                    pressedScale: 0.88,
                    onTap: audioHandler.skipToNext,
                    child: Container(
                      width: 66,
                      height: 66,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(color: Colors.white24, width: 1.5),
                      ),
                      child: const Icon(Icons.skip_next_rounded,
                          color: Colors.white, size: 32),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 14),
              // Plain icon row instead of a grouped bar.
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceAround,
                children: [
                  for (final b in [
                    (Icons.shuffle_rounded, shuffle, () {
                      audioHandler.setShuffleMode(shuffle
                          ? AudioServiceShuffleMode.none
                          : AudioServiceShuffleMode.all);
                    }),
                    (
                      repeat == AudioServiceRepeatMode.one
                          ? Icons.repeat_one_rounded
                          : Icons.repeat_rounded,
                      repeat != AudioServiceRepeatMode.none,
                      () => audioHandler.setRepeatMode(_nextRepeat(repeat)),
                    ),
                    (Icons.graphic_eq_rounded, soundModified,
                        () => showPlaybackSheet(context)),
                    (Icons.ios_share_rounded, false, () => shareTrack(track)),
                    (Icons.more_horiz_rounded, false,
                        () => showAddToPlaylistSheet(context, track)),
                  ])
                    SquishyGesture(
                      pressedScale: 0.85,
                      onTap: b.$3,
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(b.$1,
                              size: 24,
                              color: b.$2 ? pal.accent : Colors.white70),
                          const SizedBox(height: 4),
                          AnimatedContainer(
                            duration: const Duration(milliseconds: 200),
                            width: b.$2 ? 5 : 0,
                            height: 5,
                            decoration: BoxDecoration(
                                color: pal.accent, shape: BoxShape.circle),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
              const SizedBox(height: 10),
            ],
          ),
        ),
      ),
    );
  }
}

AudioServiceRepeatMode _nextRepeat(AudioServiceRepeatMode r) => switch (r) {
      AudioServiceRepeatMode.none => AudioServiceRepeatMode.all,
      AudioServiceRepeatMode.all => AudioServiceRepeatMode.one,
      _ => AudioServiceRepeatMode.none,
    };

// ═══════════════════════ "Expressive" player ═══════════════════════
// Material 3 Expressive: colours from the album art, a tonal transport
// bar, a split seek slider and pill buttons along the bottom.

class ExpressivePlayerView extends StatelessWidget {
  final TrackItem track;
  final bool playing;
  final bool loading;
  final bool shuffle;
  final AudioServiceRepeatMode repeat;
  final bool liked;
  const ExpressivePlayerView({
    super.key,
    required this.track,
    required this.playing,
    required this.loading,
    required this.shuffle,
    required this.repeat,
    required this.liked,
    this.alexLayout = false,
  });

  /// AlexLMP player: same look, but shuffle / previous / round play / next /
  /// repeat in one row, and Liquid Glass when that's switched on.
  final bool alexLayout;

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Color>(
      future: artSeedFor(track),
      builder: (context, snap) {
        final cs = AppPalette.scheme(snap.data ?? track.artColors.first);
        return AnimatedTheme(
          data: ThemeData(useMaterial3: true, colorScheme: cs),
          duration: const Duration(milliseconds: 500),
          child: _body(context, cs),
        );
      },
    );
  }

  Widget _body(BuildContext context, ColorScheme cs) {
    final bg = Color.lerp(cs.surface, Colors.black, 0.25)!;
    final light = Color.lerp(cs.primary, Colors.white, 0.72)!;
    final glass = alexLayout && appState.liquidGlass;

    // A tinted pane, or a glass pane when Liquid Glass is on.
    Widget pane(Widget child, Color color, double w, double h, double r) => glass
        ? SizedBox(
            width: w,
            height: h,
            child: LiquidGlassBox(
              borderRadius: BorderRadius.circular(r),
              fallbackColor: color,
              child: Center(child: child),
            ),
          )
        : AnimatedContainer(
            duration: const Duration(milliseconds: 260),
            width: w,
            height: h,
            decoration: BoxDecoration(
              color: color,
              borderRadius: BorderRadius.circular(r),
            ),
            alignment: Alignment.center,
            child: child,
          );

    Widget tonal(Widget child, Color color, VoidCallback onTap,
            {double w = 60, double h = 60, double r = 20}) =>
        SquishyGesture(
          pressedScale: 0.9,
          onTap: onTap,
          child: pane(child, color, w, h, r),
        );

    Widget bottomPill(IconData icon, String label, VoidCallback onTap) =>
        Expanded(
          child: SquishyGesture(
            pressedScale: 0.95,
            onTap: onTap,
            child: pane(Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(icon, color: cs.onSurface, size: 21),
                  const SizedBox(width: 8),
                  Text(label,
                      style: TextStyle(
                          color: cs.onSurface,
                          fontSize: 15,
                          fontWeight: FontWeight.w500)),
                ],
              ), cs.surfaceContainerHigh, double.infinity, 50, 18),
          ),
        );

    final source = liked
        ? 'Liked'
        : track.isYouTube
            ? 'YouTube Music'
            : track.album;

    return Scaffold(
      backgroundColor: glass ? Colors.black : bg,
      body: Stack(
        fit: StackFit.expand,
        children: [
          if (glass) TinyArtBackdrop(track: track, dim: 0.5),
          SafeArea(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 22),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const SizedBox(height: 10),
              GestureDetector(
                onTap: () => Navigator.of(context).pop(),
                child: Center(
                  child: Column(
                    children: [
                      Text('Now Playing',
                          style: TextStyle(
                              color: cs.onSurface,
                              fontSize: 16,
                              fontWeight: FontWeight.w600)),
                      const SizedBox(height: 2),
                      Text(source,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: cs.onSurfaceVariant, fontSize: 13.5)),
                    ],
                  ),
                ),
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 6),
                  child: Center(
                    child: AspectRatio(
                      aspectRatio: 1,
                      child: Hero(
                        tag: 'now_playing_art',
                        createRectTween: _arcTween,
                        flightShuttleBuilder: _artShuttle,
                        child: SwipeArtCarousel(
                            track: track, playing: playing, radius: 20),
                      ),
                    ),
                  ),
                ),
              ),
              Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(track.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color: cs.onSurface,
                                fontSize: 21,
                                fontWeight: FontWeight.w700)),
                        const SizedBox(height: 2),
                        Text(track.artist,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color: cs.onSurface.withOpacity(0.85),
                                fontSize: 15.5)),
                      ],
                    ),
                  ),
                  const SizedBox(width: 10),
                  tonal(Icon(Icons.share_outlined, color: cs.onSurface, size: 20),
                      cs.surfaceContainerHigh, () => shareTrack(track),
                      w: 44, h: 44, r: 14),
                  const SizedBox(width: 8),
                  tonal(
                    Icon(
                        liked
                            ? Icons.favorite_rounded
