// ═══════════════════════ First-run setup ═══════════════════════
// AlexLMP's own onboarding: an animated welcome, permissions, an optional
// YouTube Music sign-in, "make it yours" (crossfade first), then a finish
// screen. Pure black with slowly drifting colour, segmented progress bar
// at the top, cards that slide in one after another.

/// Animated AlexLMP mark: equalizer bars that bounce inside a glowing ring.
class AlexLogo extends StatefulWidget {
  final double size;
  final Color color;
  const AlexLogo({super.key, this.size = 120, required this.color});

  @override
  State<AlexLogo> createState() => _AlexLogoState();
}

class _AlexLogoState extends State<AlexLogo>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1400),
  )..repeat();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final s = widget.size;
    return AnimatedBuilder(
      animation: _c,
      builder: (context, _) {
        final t = _c.value * 2 * pi;
        return Container(
          width: s,
          height: s,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            gradient: SweepGradient(
              transform: GradientRotation(t / 2),
              colors: [
                widget.color,
                Color.lerp(widget.color, Colors.white, 0.5)!,
                widget.color.withOpacity(0.4),
                widget.color,
              ],
            ),
            boxShadow: [
              BoxShadow(
                color: widget.color.withOpacity(0.35 + 0.15 * sin(t)),
                blurRadius: 40,
                spreadRadius: 2,
              ),
            ],
          ),
          padding: EdgeInsets.all(s * 0.045),
          child: Container(
            decoration: const BoxDecoration(
              color: Colors.black,
              shape: BoxShape.circle,
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                for (var i = 0; i < 5; i++)
                  Container(
                    margin: EdgeInsets.symmetric(horizontal: s * 0.025),
                    width: s * 0.06,
                    height: s *
                        (0.14 + 0.24 * (0.5 + 0.5 * sin(t + i * 1.1)).abs()),
                    decoration: BoxDecoration(
                      color: Color.lerp(
                          widget.color, Colors.white, 0.15 * (i % 2)),
                      borderRadius: BorderRadius.circular(s),
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class SetupScreen extends StatefulWidget {
  const SetupScreen({super.key});

  @override
  State<SetupScreen> createState() => _SetupScreenState();
}

class _SetupScreenState extends State<SetupScreen> {
  static const _card = Color(0xFF111114);
  static const _soft = Color(0xFFA9ABB8);

  int _page = 0;
  int _dir = 1;
  bool _notif = false;
  bool _storage = false;
  bool _battery = false;
  AppLifecycleListener? _life;

  static const _pageCount = 5;

  @override
  void initState() {
    super.initState();
    _refresh();
    _life = AppLifecycleListener(onResume: _refresh);
  }

  @override
  void dispose() {
    _life?.dispose();
    super.dispose();
  }

  Future<void> _refresh() async {
    if (!Platform.isAndroid) return;
    try {
      final n = await Permission.notification.isGranted;
      final s = await Permission.audio.isGranted ||
          await Permission.storage.isGranted;
      final b = await Permission.ignoreBatteryOptimizations.isGranted;
      if (mounted) {
        setState(() {
          _notif = n;
          _storage = s;
          _battery = b;
        });
      }
    } catch (_) {}
  }

  Future<void> _ask(Future<void> Function() request) async {
    HapticFeedback.selectionClick();
    try {
      await request();
    } catch (_) {}
    await _refresh();
  }

  void _go(int to) {
    HapticFeedback.selectionClick();
    setState(() {
      _dir = to > _page ? 1 : -1;
      _page = to;
    });
  }

  void _finish() {
    HapticFeedback.mediumImpact();
    appState.setB('setup_done', true);
  }

  // ── Pieces ──────────────────────────────────────────────────────────

  Widget _heading(IconData icon, String kicker, String title, String body,
      Color accent) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const SizedBox(height: 26),
        Reveal(
          child: Row(
            children: [
              Container(
                width: 40,
                height: 40,
                decoration: BoxDecoration(
                  color: accent.withOpacity(0.16),
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: accent.withOpacity(0.45)),
                ),
                child: Icon(icon, color: accent, size: 22),
              ),
              const SizedBox(width: 12),
              Text(
                kicker.toUpperCase(),
                style: TextStyle(
                  color: accent,
                  fontSize: 12.5,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 1.6,
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 18),
        Reveal(
          delayMs: 60,
          child: Text(
            title,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 34,
              fontWeight: FontWeight.w800,
              height: 1.1,
              letterSpacing: -0.8,
            ),
          ),
        ),
        const SizedBox(height: 10),
        Reveal(
          delayMs: 110,
          child: Text(
            body,
            style: const TextStyle(color: _soft, fontSize: 16.5, height: 1.45),
          ),
        ),
        const SizedBox(height: 24),
      ],
    );
  }

  Widget _card2({required Widget child, int delay = 0, Color? border}) {
    return Reveal(
      delayMs: 160 + delay,
      child: Container(
        margin: const EdgeInsets.only(bottom: 12),
