  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: appState,
      builder: (context, _) {
        final accent = Color.lerp(appState.palette.accent, Colors.white, 0.1)!;
        final pages = [_welcome, _permissions, _account, _look, _done];
        final last = _page == _pageCount - 1;
        final bottom = MediaQuery.of(context).padding.bottom;
        return Theme(
          data: ThemeData(
            useMaterial3: true,
            brightness: Brightness.dark,
            colorScheme: AppPalette.scheme(accent),
          ),
          child: Scaffold(
            backgroundColor: Colors.black,
            body: Stack(
              fit: StackFit.expand,
              children: [
                AmoledGlow(accent: accent),
                SafeArea(
                  bottom: false,
                  child: Column(
                    children: [
                      // Segmented progress bar.
                      Padding(
                        padding: const EdgeInsets.fromLTRB(22, 14, 22, 0),
                        child: Row(
                          children: [
                            for (var i = 0; i < _pageCount; i++)
                              Expanded(
                                child: AnimatedContainer(
                                  duration: const Duration(milliseconds: 400),
                                  curve: Curves.easeOutCubic,
                                  margin: const EdgeInsets.symmetric(horizontal: 3),
                                  height: 4,
                                  decoration: BoxDecoration(
                                    color: i <= _page
                                        ? accent
                                        : Colors.white.withOpacity(0.12),
                                    borderRadius: BorderRadius.circular(2),
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                      Expanded(
                        child: AnimatedSwitcher(
                          duration: const Duration(milliseconds: 380),
                          switchInCurve: kEmphasizedDecel,
                          switchOutCurve: Curves.easeIn,
                          transitionBuilder: (c, a) {
                            final incoming = c.key == ValueKey(_page);
                            return FadeTransition(
                              opacity: a,
                              child: SlideTransition(
                                position: Tween<Offset>(
                                  begin: Offset(
                                      0.12 * (incoming ? _dir : -_dir), 0),
                                  end: Offset.zero,
                                ).animate(a),
                                child: c,
                              ),
                            );
                          },
                          child: ListView(
                            key: ValueKey(_page),
                            padding: const EdgeInsets.fromLTRB(22, 4, 22, 30),
                            children: pages[_page](accent),
                          ),
                        ),
                      ),
                      Padding(
                        padding: EdgeInsets.fromLTRB(22, 10, 22, bottom + 16),
                        child: Row(
                          children: [
                            AnimatedSwitcher(
                              duration: const Duration(milliseconds: 250),
                              child: _page > 0 && !last
                                  ? Padding(
                                      key: const ValueKey('back'),
                                      padding: const EdgeInsets.only(right: 12),
                                      child: SquishyGesture(
                                        onTap: () => _go(_page - 1),
                                        child: Container(
                                          width: 56,
                                          height: 56,
                                          decoration: BoxDecoration(
                                            shape: BoxShape.circle,
                                            color: Colors.white.withOpacity(0.06),
                                            border:
                                                Border.all(color: Colors.white12),
                                          ),
                                          child: const Icon(
                                              Icons.arrow_back_rounded,
                                              color: Colors.white),
                                        ),
                                      ),
                                    )
                                  : const SizedBox(key: ValueKey('none')),
                            ),
                            Expanded(
                              child: SquishyGesture(
                                pressedScale: 0.97,
                                onTap: () =>
                                    last ? _finish() : _go(_page + 1),
                                child: AnimatedContainer(
                                  duration: const Duration(milliseconds: 300),
                                  height: 56,
                                  decoration: BoxDecoration(
                                    color: accent,
                                    borderRadius: BorderRadius.circular(18),
                                    boxShadow: [
                                      BoxShadow(
                                        color: accent.withOpacity(0.35),
                                        blurRadius: 22,
                                        offset: const Offset(0, 8),
                                      ),
                                    ],
                                  ),
                                  child: Row(
                                    mainAxisAlignment: MainAxisAlignment.center,
                                    children: [
                                      ValueListenableBuilder<YtAccount>(
                                        valueListenable: ytAccount,
                                        builder: (_, acc, __) => Text(
                                          _page == 0
                                              ? 'Get started'
                                              : last
                                                  ? 'Start listening'
                                                  : (_page == 2 && !acc.signedIn)
                                                      ? 'Skip for now'
                                                      : 'Continue',
                                          style: const TextStyle(
                                            color: Colors.black,
                                            fontSize: 17,
                                            fontWeight: FontWeight.w800,
                                          ),
                                        ),
                                      ),
                                      const SizedBox(width: 8),
                                      const Icon(Icons.arrow_forward_rounded,
                                          color: Colors.black, size: 20),
                                    ],
                                  ),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

// ═══════════════════════ Big artwork (double-tap) ═══════════════════════

/// Player styles that support big edge-to-edge artwork.
const kImmersivePlayers = {'simp', 'alex', 'plus'};

/// Edge-to-edge artwork filling the top of the player, fading out at the
/// bottom into whatever is behind it. Double-tap it to go back.
class ImmersiveArt extends StatelessWidget {
  final TrackItem track;
  final bool playing;
  const ImmersiveArt({super.key, required this.track, required this.playing});

  @override
  Widget build(BuildContext context) {
    final h = MediaQuery.of(context).size.height * 0.6;
    return SizedBox(
      height: h,
      width: double.infinity,
      child: RepaintBoundary(
        child: Stack(
          fit: StackFit.expand,
          children: [
            ShaderMask(
              blendMode: BlendMode.dstIn,
              shaderCallback: (r) => const LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [Colors.white, Colors.white, Colors.transparent],
                stops: [0, 0.6, 1],
              ).createShader(r),
              child: Hero(
                tag: 'now_playing_art',
                createRectTween: _arcTween,
                flightShuttleBuilder: _artShuttle,
                child: SwipeArtCarousel(
                    track: track, playing: playing, radius: 0, plain: true),
              ),
            ),
            // Keeps the top buttons readable on bright covers.
            const IgnorePointer(
              child: DecoratedBox(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [Color(0x73000000), Color(0x00000000)],
                    stops: [0, 0.25],
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ═══════════════════════ SimpMusic-style player ═══════════════════════
// Connected button groups: pressing a button stretches it wider and squeezes
// its neighbours, then everything springs back with a little bounce. The
// play button is a pill when paused and a rounded rectangle while playing.
// Colours follow the song and blend smoothly when it changes.

/// A row of buttons that share one width. Pressing one grows it and takes
/// the space from the buttons right next to it.
class SquishGroup extends StatefulWidget {
  final int count;
  final double height;
  final double gap;

  /// Relative widths; 0 means "a circle" (width = height).
  final List<double> flex;

  /// How much each button grows when pressed, as a share of the row width.
  final List<double> grow;
  final Widget Function(BuildContext context, int i, double width, double press)
      builder;
  final void Function(int i) onTap;

  const SquishGroup({
    super.key,
    required this.count,
    required this.height,
    required this.flex,
    required this.grow,
    required this.builder,
    required this.onTap,
    this.gap = 8,
  });

  @override
  State<SquishGroup> createState() => _SquishGroupState();
}

class _SquishGroupState extends State<SquishGroup>
    with TickerProviderStateMixin {
  late final List<AnimationController> _p = [
    for (var i = 0; i < widget.count; i++)
      AnimationController.unbounded(vsync: this, value: 0)
  ];
  late final List<DateTime?> _downAt = List.filled(widget.count, null);

  @override
  void dispose() {
    for (final c in _p) {
      c.dispose();
    }
    super.dispose();
  }

  void _press(int i) {
    _downAt[i] = DateTime.now();
    HapticFeedback.lightImpact();
    _p[i].animateWith(SpringSimulation(
      const SpringDescription(mass: 1, stiffness: 900, damping: 40),
      _p[i].value,
      1,
      _p[i].velocity,
    ));
  }

  Future<void> _release(int i) async {
    // Keep the squish visible for a moment even on a very quick tap.
    final held = DateTime.now().difference(_downAt[i] ?? DateTime.now());
    const minHold = Duration(milliseconds: 150);
    if (held < minHold) await Future<void>.delayed(minHold - held);
    if (!mounted) return;
    _p[i].animateWith(SpringSimulation(
      const SpringDescription(mass: 1, stiffness: 520, damping: 17),
      _p[i].value,
      0,
      _p[i].velocity,
    ));
  }

  @override
  Widget build(BuildContext context) {
    final n = widget.count;
    return LayoutBuilder(builder: (context, c) {
      final total = c.maxWidth - widget.gap * (n - 1);
      var fixed = 0.0, flexSum = 0.0;
      for (final f in widget.flex) {
        if (f == 0) {
          fixed += widget.height;
        } else {
          flexSum += f;
        }
      }
      final per = flexSum == 0 ? 0.0 : (total - fixed) / flexSum;
      final base = [
        for (final f in widget.flex) f == 0 ? widget.height : f * per
      ];
      return AnimatedBuilder(
        animation: Listenable.merge(_p),
        builder: (context, _) {
          final g = [
            for (var i = 0; i < n; i++) widget.grow[i] * total * _p[i].value
          ];
          final w = List<double>.of(base);
          for (var i = 0; i < n; i++) {
            if (g[i] == 0) continue;
            final hasL = i > 0, hasR = i < n - 1;
            final share = g[i] / ((hasL ? 1 : 0) + (hasR ? 1 : 0));
            w[i] += g[i];
            if (hasL) w[i - 1] -= share;
            if (hasR) w[i + 1] -= share;
          }
          return SizedBox(
            height: widget.height,
            child: Row(
              children: [
                for (var i = 0; i < n; i++) ...[
                  if (i > 0) SizedBox(width: widget.gap),
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTapDown: (_) => _press(i),
                    onTapUp: (_) {
                      _release(i);
                      widget.onTap(i);
                    },
                    onTapCancel: () => _release(i),
                    child: SizedBox(
                      width: max(12.0, w[i]),
                      height: widget.height,
                      child: widget.builder(
                          context, i, max(12.0, w[i]), _p[i].value),
                    ),
                  ),
                ],
              ],
            ),
          );
        },
      );
    });
  }
}

/// Thick track with a tall bar thumb and a gap around it.
class _SimpSeekPainter extends CustomPainter {
  final double value;
  final bool dragging;
  final Color active;
  final Color inactive;
  _SimpSeekPainter(this.value, this.dragging, this.active, this.inactive);

  @override
  void paint(Canvas canvas, Size size) {
    const trackH = 6.0;
    final cy = size.height / 2;
    final thumbW = dragging ? 3.0 : 4.0;
    const gap = 5.0;
    final x = (size.width * value).clamp(thumbW / 2, size.width - thumbW / 2);
    final r = const Radius.circular(3);
    if (x - gap - thumbW / 2 > 0) {
      canvas.drawRRect(
        RRect.fromLTRBAndCorners(0, cy - trackH / 2, x - gap - thumbW / 2,
            cy + trackH / 2,
            topLeft: r, bottomLeft: r, topRight: const Radius.circular(1.5),
            bottomRight: const Radius.circular(1.5)),
        Paint()..color = active,
      );
    }
    if (x + gap + thumbW / 2 < size.width) {
      canvas.drawRRect(
        RRect.fromLTRBAndCorners(x + gap + thumbW / 2, cy - trackH / 2,
            size.width, cy + trackH / 2,
            topRight: r, bottomRight: r, topLeft: const Radius.circular(1.5),
            bottomLeft: const Radius.circular(1.5)),
        Paint()..color = inactive,
      );
      // Stop dot at the end.
      canvas.drawCircle(
          Offset(size.width - 4, cy), 2, Paint()..color = active);
    }
    final th = dragging ? 26.0 : 22.0;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(x, cy), width: thumbW, height: th),
          Radius.circular(thumbW)),
      Paint()..color = active,
    );
  }

  @override
  bool shouldRepaint(_SimpSeekPainter o) =>
      o.value != value ||
      o.dragging != dragging ||
      o.active != active ||
      o.inactive != inactive;
}

class SimpPlayerView extends StatelessWidget {
  final TrackItem track;
  final bool playing;
  final bool loading;
  final bool shuffle;
  final AudioServiceRepeatMode repeat;
  final bool liked;
  const SimpPlayerView({
    super.key,
    required this.track,
    required this.playing,
    required this.loading,
    required this.shuffle,
    required this.repeat,
    required this.liked,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Color>(
      future: artSeedFor(track),
      builder: (context, snap) {
        final seed = snap.data ?? track.artColors.first;
        return AnimatedTheme(
          data: ThemeData(
            useMaterial3: true,
            brightness: Brightness.dark,
            colorScheme: AppPalette.scheme(seed),
          ),
          duration: const Duration(milliseconds: 450),
          child: Builder(builder: (context) => _body(context)),
        );
      },
    );
  }

  void _more(BuildContext context, ColorScheme cs) {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: cs.surfaceContainerHigh,
      showDragHandle: true,
      builder: (ctx) {
        Widget item(IconData i, String t, VoidCallback f) => ListTile(
              leading: Icon(i, color: cs.onSurfaceVariant),
              title: Text(t, style: TextStyle(color: cs.onSurface)),
              onTap: () {
                Navigator.pop(ctx);
                f();
              },
            );
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              item(Icons.playlist_add_rounded, 'Add to playlist',
                  () => showAddToPlaylistSheet(context, track)),
              item(Icons.graphic_eq_rounded, 'Sound & speed',
                  () => showPlaybackSheet(context)),
              item(Icons.bedtime_outlined, 'Sleep timer',
                  () => showSleepTimerSheet(context)),
              item(Icons.person_rounded, 'Go to artist',
                  () => goToArtist(context, track)),
              item(Icons.ios_share_rounded, 'Share', () => shareTrack(track)),
            ],
          ),
        );
      },
    );
  }

  Widget _body(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final immersive = appState.b('immersive_art');
    final source = liked
        ? 'Your likes'
        : track.isYouTube
            ? 'Streaming'
            : 'On this phone';

    Widget tonal(IconData icon, VoidCallback onTap, {bool on = false}) =>
        SquishyGesture(
          pressedScale: 0.88,
          onTap: onTap,
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 300),
            width: 42,
            height: 34,
            decoration: BoxDecoration(
              color: on ? cs.primary : cs.primaryContainer,
              borderRadius: BorderRadius.circular(10),
            ),
            child: Icon(icon,
                size: 19, color: on ? cs.onPrimary : cs.onPrimaryContainer),
          ),
        );

    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          AnimatedContainer(
            duration: const Duration(milliseconds: 450),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [
                  Color.lerp(Colors.black, cs.primary, 0.24)!,
                  Color.lerp(Colors.black, cs.primary, 0.08)!,
                  Colors.black,
                ],
                stops: const [0, 0.45, 0.8],
              ),
            ),
          ),
          if (immersive)
            Positioned(
              top: 0,
              left: 0,
              right: 0,
              child: ImmersiveArt(track: track, playing: playing),
            ),
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20),
              child: Column(
                children: [
                  const SizedBox(height: 14),
                  Text('NOW PLAYING',
                      style: TextStyle(
                          color: cs.onSurface,
                          fontSize: 12,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 1.2)),
                  const SizedBox(height: 2),
                  Text(source,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                          color: cs.onSurfaceVariant, fontSize: 12.5)),
                  if (immersive) const Spacer() else Expanded(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 22),
                      child: Center(
                        child: AspectRatio(
                          aspectRatio: 1,
                          child: Hero(
                            tag: 'now_playing_art',
                            createRectTween: _arcTween,
                            flightShuttleBuilder: _artShuttle,
                            child: SwipeArtCarousel(
                                track: track,
                                playing: playing,
                                radius: appState.vinylSpinMode ? 999 : 14),
                          ),
                        ),
                      ),
                    ),
                  ),
                  // ── Title + small tonal buttons
                  Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(track.title,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    color: cs.onSurface,
                                    fontSize: 18,
                                    fontWeight: FontWeight.w700)),
                            GestureDetector(
                              onTap: () => goToArtist(context, track),
                              child: Text(track.artist,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                      color: cs.onSurfaceVariant,
                                      fontSize: 14.5)),
                            ),
                          ],
                        ),
                      ),
                      if (track.isYouTube) ...[
                        ValueListenableBuilder<int>(
                          valueListenable: OfflineStore.revision,
                          builder: (_, __, ___) {
                            final saved = OfflineStore.isDownloaded(track);
                            return tonal(
                              saved
                                  ? Icons.download_done_rounded
                                  : Icons.download_rounded,
                              () {
                                if (!OfflineStore.isBusy(track)) {
                                  toggleOffline(track);
                                }
                              },
                              on: saved,
                            );
                          },
                        ),
                        const SizedBox(width: 6),
                      ],
                      tonal(
                        liked
                            ? Icons.favorite_rounded
                            : Icons.favorite_border_rounded,
                        () {
                          HapticFeedback.lightImpact();
                          appState.toggleLike(track.id);
                        },
                        on: liked,
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  // ── Seek bar
                  PlayerSeek(
                    fallbackSeconds: track.durationSeconds,
                    height: 30,
                    timeStyle: TextStyle(
                      color: cs.onSurfaceVariant,
                      fontSize: 11.5,
                      fontFeatures: const [ui.FontFeature.tabularFigures()],
                    ),
                    track: (v, dragging) => CustomPaint(
                      painter: _SimpSeekPainter(
                          v, dragging, cs.primary, cs.secondaryContainer),
                    ),
                  ),
                  const SizedBox(height: 10),
                  // ── Prev · Play · Next (connected, squishy)
                  SquishGroup(
                    count: 3,
                    height: 68,
                    gap: 8,
                    flex: const [0, 1, 0],
                    grow: const [0.09, 0.13, 0.09],
                    onTap: (i) {
                      if (i == 0) {
                        audioHandler.skipToPrevious();
                      } else if (i == 2) {
                        audioHandler.skipToNext();
                      } else {
                        playing ? audioHandler.pause() : audioHandler.play();
                      }
                    },
                    builder: (context, i, w, p) {
                      if (i == 1) {
                        return TweenAnimationBuilder<double>(
                          tween: Tween(end: playing ? 20.0 : 34.0),
                          duration: const Duration(milliseconds: 420),
                          curve: Curves.easeOutBack,
                          builder: (_, r, child) => AnimatedContainer(
                            duration: const Duration(milliseconds: 450),
                            decoration: BoxDecoration(
                              color: cs.primary,
                              borderRadius:
                                  BorderRadius.circular(r.clamp(4.0, 34.0)),
                            ),
                            alignment: Alignment.center,
                            child: child,
                          ),
                          child: loading
                              ? SizedBox(
                                  width: 24,
                                  height: 24,
                                  child: CircularProgressIndicator(
                                      strokeWidth: 3,
                                      strokeCap: StrokeCap.round,
                                      color: cs.onPrimary),
                                )
                              : AnimatedSwitcher(
                                  duration: const Duration(milliseconds: 220),
                                  transitionBuilder: (c, a) =>
                                      ScaleTransition(scale: a, child: c),
                                  child: Icon(
                                    playing
                                        ? Icons.pause_rounded
                                        : Icons.play_arrow_rounded,
                                    key: ValueKey(playing),
                                    color: cs.onPrimary,
                                    size: 32,
                                  ),
                                ),
                        );
                      }
                      return AnimatedContainer(
                        duration: const Duration(milliseconds: 450),
                        decoration: BoxDecoration(
                          color: cs.secondaryContainer,
                          borderRadius: BorderRadius.circular(34),
                        ),
                        alignment: Alignment.center,
                        child: Icon(
                          i == 0
                              ? Icons.skip_previous_rounded
                              : Icons.skip_next_rounded,
                          color: cs.onSecondaryContainer,
                          size: 26,
                        ),
                      );
                    },
                  ),
                  const SizedBox(height: 14),
                  // ── Lyrics · Shuffle · Repeat · Queue · More
                  SquishGroup(
                    count: 5,
                    height: 40,
                    gap: 8,
                    flex: const [1, 1, 1, 1, 0],
                    grow: const [0.07, 0.07, 0.07, 0.07, 0.05],
                    onTap: (i) {
                      switch (i) {
                        case 0:
                          showLyricsSheet(context, track);
                        case 1:
                          audioHandler.setShuffleMode(shuffle
                              ? AudioServiceShuffleMode.none
                              : AudioServiceShuffleMode.all);
                        case 2:
                          audioHandler.setRepeatMode(_nextRepeat(repeat));
                        case 3:
                          showQueueSheet(context);
                        default:
                          _more(context, cs);
                      }
                    },
                    builder: (context, i, w, p) {
                      final on = (i == 1 && shuffle) ||
                          (i == 2 && repeat != AudioServiceRepeatMode.none);
                      final icon = switch (i) {
                        0 => Icons.lyrics_outlined,
                        1 => Icons.shuffle_rounded,
                        2 => repeat == AudioServiceRepeatMode.one
                            ? Icons.repeat_one_rounded
                            : Icons.repeat_rounded,
                        3 => Icons.queue_music_rounded,
                        _ => Icons.more_vert_rounded,
                      };
                      return AnimatedContainer(
                        duration: const Duration(milliseconds: 300),
                        decoration: BoxDecoration(
                          color: i == 4
                              ? cs.secondaryContainer
                              : on
                                  ? cs.primary
                                  : cs.surfaceContainerHigh,
                          borderRadius: BorderRadius.circular(i == 4 ? 20 : 12),
                        ),
                        alignment: Alignment.center,
                        child: Icon(icon,
                            size: 20,
                            color: i == 4
                                ? cs.onSecondaryContainer
                                : on
                                    ? cs.onPrimary
                                    : cs.onSurfaceVariant),
                      );
                    },
                  ),
                  const SizedBox(height: 16),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// ═══════════════════════ PLUS ═══════════════════════
// AlexLMP's own design. Pure black, one accent colour, a bento grid of
// tiles on Home, numbered picks, and a player with a "barcode" seek bar
// and a play button that morphs between a rounded square and a circle.
// Everything is static drawing (no blur, no full-screen animation) so it
// stays smooth on any phone.

const _plusCard = Color(0xFF121216);
const _plusLine = Color(0xFF1E1E24);

/// A tile in the PLUS bento grid.
class PlusTile extends StatelessWidget {
  final double width;
  final double height;
  final Widget child;
  final VoidCallback? onTap;
  final Color color;
  final EdgeInsetsGeometry padding;
  const PlusTile({
    super.key,
    required this.width,
    required this.height,
    required this.child,
    this.onTap,
    this.color = _plusCard,
    this.padding = const EdgeInsets.all(14),
  });

  @override
  Widget build(BuildContext context) {
    return SquishyGesture(
      pressedScale: 0.96,
      onTap: onTap == null
          ? null
          : () {
              HapticFeedback.selectionClick();
              onTap!();
            },
      child: Container(
        width: width,
        height: height,
        padding: padding,
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: color,
          borderRadius: BorderRadius.circular(24),
        ),
        child: child,
      ),
    );
  }
}

