/// Donation links (Settings → Support AlexLMP).
const String kDonateCashApp = 'https://cash.app/\$sxlocctrapp';
const String kDonatePayPal = 'https://paypal.me/alexdesrosier67';

const String kGithubRepo = 'cashhwocky/AlexLMP';

class AppRelease {
  final String version;
  final String title;
  final String notes;
  final String pageUrl;
  final String? apkUrl;
  const AppRelease(this.version, this.title, this.notes, this.pageUrl, this.apkUrl);
  String get downloadUrl => apkUrl ?? pageUrl;
}

/// Compares "2.10.1" style versions (a leading "v" and any "-beta" are ignored).
int compareVersions(String a, String b) {
  List<int> parts(String v) => v
      .trim()
      .replaceFirst(RegExp(r'^[vV]'), '')
      .split(RegExp(r'[-+ ]'))
      .first
      .split('.')
      .map((x) => int.tryParse(x) ?? 0)
      .toList();
  final pa = parts(a), pb = parts(b);
  for (var i = 0; i < max(pa.length, pb.length); i++) {
    final x = i < pa.length ? pa[i] : 0;
    final y = i < pb.length ? pb[i] : 0;
    if (x != y) return x.compareTo(y);
  }
  return 0;
}

Future<AppRelease> fetchLatestRelease() async {
  if (kGithubRepo.startsWith('YOUR-')) {
    throw Exception('kGithubRepo is not set in main.dart');
  }
  final client = HttpClient()..connectionTimeout = const Duration(seconds: 10);
  try {
    final req = await client
        .getUrl(Uri.parse('https://api.github.com/repos/$kGithubRepo/releases/latest'));
    req.headers.set('User-Agent', 'AlexLMP/$kAppVersion');
    req.headers.set('Accept', 'application/vnd.github+json');
    final res = await req.close();
    final body = await utf8.decoder.bind(res).join();
    if (res.statusCode != 200) {
      throw Exception('GitHub answered ${res.statusCode}: $body');
    }
    final m = Map<String, dynamic>.from(jsonDecode(body) as Map);
    final tag = (m['tag_name'] ?? '').toString();
    String? apk;
    for (final a in (m['assets'] as List? ?? const [])) {
      final am = Map<String, dynamic>.from(a as Map);
      final name = (am['name'] ?? '').toString().toLowerCase();
      if (name.endsWith('.apk')) {
        apk = (am['browser_download_url'] ?? '').toString();
        break;
      }
    }
    return AppRelease(
      tag.replaceFirst(RegExp(r'^[vV]'), ''),
      (m['name'] ?? tag).toString(),
      (m['body'] ?? '').toString(),
      (m['html_url'] ?? 'https://github.com/$kGithubRepo/releases').toString(),
      apk,
    );
  } finally {
    client.close();
  }
}

Future<void> openExternalUrl(String url) async {
  try {
    await _mediaChannel.invokeMethod('openUrl', {'url': url});
  } catch (e) {
    await Clipboard.setData(ClipboardData(text: url));
    appNotice.value = 'Couldn\'t open the link, so it was copied instead. ($e)';
  }
}

/// Markdown -> readable plain text for the dialog.
String _plainNotes(String md) => md
    .replaceAll(RegExp(r'^#{1,6}\s*', multiLine: true), '')
    .replaceAll('**', '')
    .replaceAll('`', '')
    .replaceAll(RegExp(r'^\s*[-*]\s+', multiLine: true), '•  ')
    .replaceAll(RegExp(r'^-{3,}\s*$', multiLine: true), '')
    .trim();

/// Checks for a newer release. [manual] = the user tapped "Check for updates"
/// (always checks, and also reports "you're up to date" / errors).
Future<void> checkForUpdates(BuildContext context, {bool manual = false}) async {
  final prefs = YouTubeMusic.prefs;
  if (!manual) {
    if (!appState.b('update_check', true)) return;
    final last = prefs?.getInt('update_last_check') ?? 0;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - last < const Duration(hours: 6).inMilliseconds) return;
    await prefs?.setInt('update_last_check', now);
  }
  AppRelease rel;
  try {
    rel = await fetchLatestRelease();
  } catch (e) {
    if (manual) appNotice.value = 'Update check failed: $e';
    return;
  }
  final newer = compareVersions(rel.version, kAppVersion) > 0;
  if (!newer) {
    if (manual) appNotice.value = 'You\'re up to date (AlexLMP $kAppVersion).';
    return;
  }
  if (!manual && prefs?.getString('update_skip') == rel.version) return;

  // System notification (stays in the shade until tapped).
  try {
    await _mediaChannel.invokeMethod('showUpdateNotification', {
      'title': 'AlexLMP ${rel.version} is available',
      'text': 'Tap to download the update.',
      'url': rel.downloadUrl,
    });
  } catch (_) {}

  if (!context.mounted) return;
  final pal = appState.palette;
  await showDialog<void>(
    context: context,
    builder: (ctx) => AlertDialog(
      icon: Icon(Icons.system_update_rounded, color: pal.accent, size: 34),
      title: Text('Update available'),
      content: ConstrainedBox(
        constraints: BoxConstraints(
            maxHeight: MediaQuery.of(ctx).size.height * 0.5),
        child: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(rel.title,
                  style: const TextStyle(
                      fontWeight: FontWeight.w700, fontSize: 17)),
              const SizedBox(height: 4),
              Text('You have $kAppVersion  →  new ${rel.version}',
                  style: const TextStyle(color: Colors.white60)),
              if (rel.notes.trim().isNotEmpty) ...[
                const SizedBox(height: 14),
                SelectableText(_plainNotes(rel.notes),
                    style: const TextStyle(height: 1.4)),
              ],
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () {
            prefs?.setString('update_skip', rel.version);
            Navigator.pop(ctx);
          },
          child: const Text('Skip this version'),
        ),
        TextButton(
          onPressed: () => Navigator.pop(ctx),
          child: const Text('Later'),
        ),
        FilledButton.icon(
          onPressed: () {
            Navigator.pop(ctx);
            openExternalUrl(rel.downloadUrl);
          },
          icon: const Icon(Icons.download_rounded),
          label: const Text('Download'),
        ),
      ],
    ),
  );
}

// ═══════════════════════ Offline saves ═══════════════════════
// Songs are downloaded whole into the app's private storage (not the
// phone's Music folder) and play from there with no internet. Artwork is
// saved next to them so covers show offline too.

class OfflineStore {
  static final ValueNotifier<int> revision = ValueNotifier<int>(0);

  /// videoId -> progress (0..1) for saves that are queued or running.
  static final ValueNotifier<Map<String, double>> active =
      ValueNotifier<Map<String, double>>(const {});

  static final Map<String, Map<String, dynamic>> _items = {};
  static bool _loaded = false;
  static final List<TrackItem> _queue = [];
  static bool _running = false;
  static int _batchDone = 0;
  static int _batchFailed = 0;

  static void _load() {
    if (_loaded) return;
    final prefs = YouTubeMusic.prefs;
    if (prefs == null) return;
    _loaded = true;
    try {
      final raw = prefs.getString('offline_tracks');
      if (raw == null) return;
      (jsonDecode(raw) as Map).forEach((k, v) {
        if (v is Map) _items[k.toString()] = Map<String, dynamic>.from(v);
      });
    } catch (_) {}
  }

  static void _save() {
    try {
      YouTubeMusic.prefs?.setString('offline_tracks', jsonEncode(_items));
    } catch (_) {}
    revision.value++;
  }

  static bool isDownloaded(TrackItem t) {
    final id = t.ytVideoId;
    if (id == null) return false;
    _load();
    return _items.containsKey(id);
  }

  static bool isBusy(TrackItem t) =>
      t.ytVideoId != null && active.value.containsKey(t.ytVideoId);

  static String? pathForVideo(String videoId) {
    _load();
    final p = _items[videoId]?['path'] as String?;
    if (p == null) return null;
    try {
      if (File(p).existsSync()) return p;
    } catch (_) {}
    return null;
  }

  static String? artPathFor(TrackItem t) {
    final id = t.ytVideoId;
    if (id == null) return null;
    _load();
    final p = _items[id]?['art'] as String?;
    if (p == null) return null;
    try {
      if (File(p).existsSync()) return p;
    } catch (_) {}
    return null;
  }

  /// Saved songs, newest first.
  static List<TrackItem> tracks() {
    _load();
    final entries = _items.entries.toList()
      ..sort((a, b) => ((b.value['at'] as num?) ?? 0)
          .compareTo((a.value['at'] as num?) ?? 0));
    final out = <TrackItem>[];
    for (var i = 0; i < entries.length; i++) {
      final m = entries[i].value['track'];
      if (m is! Map) continue;
      final t = TrackItem.fromYtJson(Map<String, dynamic>.from(m), i);
      if (t != null) out.add(audioHandler.trackById(t.id) ?? t);
    }
    return out;
  }

  static int get count {
    _load();
    return _items.length;
  }

  static int get totalBytes {
    _load();
    var n = 0;
    for (final v in _items.values) {
      n += (v['bytes'] as num?)?.toInt() ?? 0;
    }
    return n;
  }

  static String formatBytes(int b) {
    if (b >= 1024 * 1024 * 1024) {
      return '${(b / (1024 * 1024 * 1024)).toStringAsFixed(2)} GB';
    }
    if (b >= 1024 * 1024) return '${(b / (1024 * 1024)).toStringAsFixed(1)} MB';
    if (b >= 1024) return '${(b / 1024).toStringAsFixed(0)} KB';
    return '$b B';
  }

  static void _setActive(String id, double? p) {
    final m = Map<String, double>.from(active.value);
    if (p == null) {
      m.remove(id);
    } else {
      m[id] = p;
    }
    active.value = m;
  }

  /// Queues one song. Returns false if it can't be saved (local file etc.).
  static bool download(TrackItem t, {bool quiet = false}) {
    final id = t.ytVideoId;
    if (id == null) return false;
    _load();
    if (_items.containsKey(id) || active.value.containsKey(id)) return true;
    _queue.add(t);
    _setActive(id, 0);
    if (!quiet) appNotice.value = 'Saving "${t.title}" for offline…';
    _pump();
    return true;
  }

  static void downloadAll(List<TrackItem> list) {
    final todo =
        list.where((t) => t.isYouTube && !isDownloaded(t) && !isBusy(t)).toList();
    if (todo.isEmpty) {
      appNotice.value = list.any((t) => t.isYouTube)
          ? 'Already saved for offline.'
          : 'Only YouTube Music songs need saving — local files already work offline.';
      return;
    }
    for (final t in todo) {
      download(t, quiet: true);
    }
    appNotice.value =
        'Saving ${todo.length} ${todo.length == 1 ? 'song' : 'songs'} for offline…';
  }

  static Future<void> _pump() async {
    if (_running) return;
    _running = true;
    _batchDone = 0;
    _batchFailed = 0;
    try {
      while (_queue.isNotEmpty) {
        final t = _queue.removeAt(0);
        final id = t.ytVideoId!;
        final poll = Timer.periodic(const Duration(milliseconds: 600), (_) async {
          try {
            final p = await _ytChannel
                .invokeMethod<double>('ytOfflineProgress', {'videoId': id});
            if (p != null && p >= 0 && active.value.containsKey(id)) {
              _setActive(id, p);
            }
          } catch (_) {}
        });
        try {
          final raw = await _ytChannel
              .invokeMethod('ytSaveOffline', {'videoId': id});
          final m = Map<String, dynamic>.from(raw as Map);
          String? art;
          try {
            final bytes = await loadArt(t);
            if (bytes != null && bytes.isNotEmpty) {
              final dir = await getApplicationDocumentsDirectory();
              final f = File('${dir.path}/offline_art/$id.img');
              await f.parent.create(recursive: true);
              await f.writeAsBytes(bytes, flush: true);
              art = f.path;
            }
          } catch (_) {}
          _items[id] = {
            'track': t.toYtJson(),
            'path': m['path'],
            'bytes': m['bytes'],
            'art': art,
            'at': DateTime.now().millisecondsSinceEpoch,
          };
          _save();
          _batchDone++;
        } catch (e) {
          _batchFailed++;
          final detail = e is PlatformException ? (e.message ?? e.code) : '$e';
          appNotice.value = 'Couldn\'t save "${t.title}": $detail';
        } finally {
          poll.cancel();
          _setActive(id, null);
        }
      }
      if (_batchDone > 0) {
        appNotice.value = _batchFailed == 0
            ? 'Saved $_batchDone ${_batchDone == 1 ? 'song' : 'songs'} for offline.'
            : 'Saved $_batchDone, $_batchFailed failed.';
      }
    } finally {
      _running = false;
    }
  }

  static Future<void> delete(TrackItem t) async {
    final id = t.ytVideoId;
    if (id == null) return;
    _load();
    final art = _items[id]?['art'] as String?;
    _items.remove(id);
    _save();
    try {
      await _ytChannel.invokeMethod('ytDeleteOffline', {'videoId': id});
    } catch (_) {}
    if (art != null) {
      try {
        await File(art).delete();
      } catch (_) {}
    }
  }

  static Future<void> deleteAll() async {
    _load();
    final arts = _items.values.map((v) => v['art'] as String?).whereType<String>();
    for (final a in arts.toList()) {
      try {
        await File(a).delete();
      } catch (_) {}
    }
    _items.clear();
    _queue.clear();
    _save();
    try {
      await _ytChannel.invokeMethod('ytDeleteAllOffline');
    } catch (_) {}
  }
}

/// Download / remove-download action for a song (used in menus).
void toggleOffline(TrackItem t) {
  if (!t.isYouTube) {
    appNotice.value = 'This song is already on your phone.';
    return;
  }
  if (OfflineStore.isDownloaded(t)) {
    OfflineStore.delete(t);
    appNotice.value = 'Removed "${t.title}" from offline.';
  } else {
    OfflineStore.download(t);
  }
}

void openDownloads(BuildContext context) {
  Navigator.of(context).push(
    MaterialPageRoute(builder: (_) => const DownloadsScreen()),
  );
}

class DownloadsScreen extends StatelessWidget {
  const DownloadsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge([
        OfflineStore.revision,
        OfflineStore.active,
        appState,
        audioHandler.currentIndex,
      ]),
      builder: (context, _) {
        final pal = appState.palette;
        final list = OfflineStore.tracks();
        final busy = OfflineStore.active.value;
        void play(int i) {
          if (list.isEmpty) return;
          audioHandler.playYouTubeList(list, i);
          openPlayer(context);
        }

        return Scaffold(
          backgroundColor: pal.bg,
          appBar: AppBar(
            backgroundColor: pal.bg,
            foregroundColor: Colors.white,
            title: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('Downloaded',
                    style: TextStyle(fontWeight: FontWeight.w800)),
                Text(
                  '${list.length} ${list.length == 1 ? 'song' : 'songs'} • ${OfflineStore.formatBytes(OfflineStore.totalBytes)}',
                  style: const TextStyle(fontSize: 13, color: Colors.white60),
                ),
              ],
            ),
            actions: [
              if (list.isNotEmpty)
                IconButton(
                  tooltip: 'Delete all downloads',
                  icon: const Icon(Icons.delete_sweep_rounded),
                  onPressed: () async {
                    final ok = await showDialog<bool>(
                      context: context,
                      builder: (ctx) => AlertDialog(
                        title: const Text('Delete all downloads?'),
                        content: Text(
                            'Frees ${OfflineStore.formatBytes(OfflineStore.totalBytes)}. Songs stay in your likes and playlists.'),
                        actions: [
                          TextButton(
                              onPressed: () => Navigator.pop(ctx, false),
                              child: const Text('Cancel')),
                          FilledButton(
                              onPressed: () => Navigator.pop(ctx, true),
                              child: const Text('Delete')),
                        ],
                      ),
                    );
                    if (ok == true) {
                      await OfflineStore.deleteAll();
                      appNotice.value = 'All downloads deleted.';
                    }
                  },
                ),
            ],
          ),
          body: ListView(
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 120),
            children: [
              if (busy.isNotEmpty) ...[
                Padding(
                  padding: const EdgeInsets.only(top: 8, bottom: 6),
                  child: Text(
                    'Saving ${busy.length} ${busy.length == 1 ? 'song' : 'songs'}…',
                    style: TextStyle(
                        color: pal.accent,
                        fontWeight: FontWeight.w700,
                        fontSize: 14),
                  ),
                ),
                ClipRRect(
                  borderRadius: BorderRadius.circular(4),
                  child: LinearProgressIndicator(
                    minHeight: 6,
                    value: busy.values.isEmpty
                        ? null
                        : busy.values.reduce((a, b) => a + b) / busy.length,
                  ),
                ),
                const SizedBox(height: 14),
              ],
              if (list.isEmpty && busy.isEmpty)
                const Padding(
                  padding: EdgeInsets.only(top: 80),
                  child: Column(
                    children: [
                      Icon(Icons.download_for_offline_rounded,
                          size: 64, color: Colors.white24),
                      SizedBox(height: 14),
                      Text('No downloads yet',
                          style: TextStyle(
                              color: Colors.white,
                              fontSize: 18,
                              fontWeight: FontWeight.w700)),
                      SizedBox(height: 6),
                      Text(
                        'Use "Download" in a song\'s ⋯ menu, or the download\nbutton on any playlist or album.',
                        textAlign: TextAlign.center,
                        style: TextStyle(color: Colors.white54),
                      ),
                    ],
                  ),
                ),
              if (list.isNotEmpty) ...[
                Row(
                  children: [
                    Expanded(
                      child: FilledButton.icon(
                        onPressed: () {
                          audioHandler
                              .setShuffleMode(AudioServiceShuffleMode.none);
                          play(0);
                        },
                        icon: const Icon(Icons.play_arrow_rounded),
                        label: const Text('Play'),
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: FilledButton.tonalIcon(
                        onPressed: () {
                          audioHandler.setShuffleMode(AudioServiceShuffleMode.all);
                          play(Random().nextInt(list.length));
                        },
                        icon: const Icon(Icons.shuffle_rounded),
                        label: const Text('Shuffle'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                for (var i = 0; i < list.length; i++)
                  TrackRow(
                    track: list[i],
                    palette: pal,
                    active: audioHandler.currentTrack?.id == list[i].id,
                    onTap: () => play(i),
                    onMore: () => showAddToPlaylistSheet(context, list[i]),
                  ),
              ],
            ],
          ),
        );
      },
    );
  }
}

// ═══════════════════════ Home screen widget ═══════════════════════
// Sends the current song (title, artist, artwork, playing) to the Android
// widget whenever it changes.

String? _widgetTrackId;
bool? _widgetPlaying;

bool _widgetSyncStarted = false;

void startWidgetSync() {
  if (_widgetSyncStarted) return;
  _widgetSyncStarted = true;
  void push() => _pushWidget();
  audioHandler.currentIndex.addListener(push);
  audioHandler.currentIndex.addListener(prefetchNeighbourArt);
  audioHandler.upNextRevision.addListener(prefetchNeighbourArt);
  prefetchNeighbourArt();
  audioHandler.libraryRevision.addListener(push);
  audioHandler.playbackState.listen((st) {
    if (st.playing != _widgetPlaying) push();
  });
  push();
}

Future<void> _pushWidget() async {
  if (!Platform.isAndroid) return;
  final t = audioHandler.currentTrack;
  final playing = audioHandler.playbackState.value.playing;
  if (t?.id == _widgetTrackId && playing == _widgetPlaying) return;
  final trackChanged = t?.id != _widgetTrackId;
  _widgetTrackId = t?.id;
  _widgetPlaying = playing;
  String? artPath;
  try {
    final dir = await getApplicationDocumentsDirectory();
    final f = File('${dir.path}/widget_art.img');
    if (t != null && trackChanged) {
      final bytes = await loadArt(t);
      if (bytes != null && bytes.isNotEmpty) {
        await f.writeAsBytes(bytes, flush: true);
      } else if (await f.exists()) {
        await f.delete();
      }
    }
    if (await f.exists()) artPath = f.path;
  } catch (_) {}
  try {
    await _mediaChannel.invokeMethod('updateWidget', {
      'title': t?.title ?? 'Nothing playing',
      'artist': t?.artist ?? 'Open AlexLMP to start',
      'playing': playing,
      'art': artPath,
      'artChanged': trackChanged,
    });
  } catch (_) {}
}

/// Soft pulsing placeholder shapes shown while content loads.
class SkeletonPulse extends StatefulWidget {
  final Widget child;
  const SkeletonPulse({super.key, required this.child});

  @override
  State<SkeletonPulse> createState() => _SkeletonPulseState();
}

class _SkeletonPulseState extends State<SkeletonPulse>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  )..repeat(reverse: true);

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FadeTransition(
      opacity: Tween<double>(begin: 0.45, end: 1.0)
          .animate(CurvedAnimation(parent: _c, curve: Curves.easeInOut)),
      child: widget.child,
    );
  }
}

